 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

/**
 * Creates and configures an Express Router for bookmark CRUD and search endpoints.
 *
 * @param service - The BookmarkService instance to bind to route handlers (defaults to singleton).
 * @returns Configured Express Router.
 *
 * @example
 * ```ts
 * const router = createBookmarksRouter(new BookmarkService());
 * app.use('/api/v1/bookmarks', router);
 * ```
 */
export function createBookmarksRouter(service: BookmarkService = bookmarkService): Router {
  const router = Router();

  /**
   * Handles GET /api/v1/bookmarks - Lists bookmarks with pagination support.
   *
   * @param req - Express request with optional `page` and `limit` query parameters.
   * @param res - Express response sending paginated bookmark results.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks?page=1&limit=20
   * router.get('/', listBookmarksHandler);
   * ```
   */
  function listBookmarksHandler(req: Request, res: Response): void {
    const query = req.query as Record<string, unknown>;
    const { page, limit } = parsePaginationParams(query);
    const paginatedResult = service.getPaginated(page, limit);
    res.status(200).json(paginatedResult);
  }

  /**
   * Handles GET /api/v1/bookmarks/search - Searches bookmarks by title (case-insensitive substring) or tags (exact match).
   *
   * @param req - Express request with required non-empty `q` query parameter.
   * @param res - Express response sending matching bookmarks or 400 error.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks/search?q=typescript
   * router.get('/search', searchBookmarksHandler);
   * ```
   */
  function searchBookmarksHandler(req: Request, res: Response): void {
    const rawQ = getQueryString(req.query.q);
    if (rawQ === undefined || rawQ.trim() === '') {
      res.status(400).json({ error: 'Search query parameter "q" is required and cannot be empty' });
      return;
    }

    const results = service.search(rawQ);
    res.status(200).json(results);
  }

  /**
   * Handles GET /api/v1/bookmarks/:id - Retrieves a single bookmark by its ID.
   *
   * @param req - Express request containing the bookmark ID parameter.
   * @param res - Express response sending the bookmark or 404 error.
   * @returns Void.
   *
   * @example
   * ```ts
   * // GET /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * router.get('/:id', getBookmarkByIdHandler);
   * ```
   */
  function getBookmarkByIdHandler(req: Request<{ id: string }>, res: Response): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const bookmark = service.findById(id);

    if (!bookmark) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(bookmark);
  }

  /**
   * Handles POST /api/v1/bookmarks - Creates a new bookmark.
   *
   * @param req - Express request containing the bookmark creation payload in body.
   * @param res - Express response sending the created bookmark with 201 or error status.
   * @param next - Express next middleware function for error delegation.
   * @returns Void.
   *
   * @example
   * ```ts
   * // POST /api/v1/bookmarks
   * // Body: { "url": "https://example.com", "title": "Example", "tags": ["web"] }
   * router.post('/', createBookmarkHandler);
   * ```
   */
  function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
    try {
      const body: unknown = req.body;
      const parseResult = createBookmarkSchema.safeParse(body);

      if (!parseResult.success) {
        next(parseResult.error);
        return;
      }

      const newBookmark = service.create(parseResult.data);

      res.status(201).json(newBookmark);
    } catch (err: unknown) {
      next(err);
    }
  }

  /**
   * Handles PATCH /api/v1/bookmarks/:id - Updates an existing bookmark's title and/or tags.
   *
   * @param req - Express request containing bookmark ID in params and updates in body.
   * @param res - Express response sending updated bookmark or error status.
   * @param next - Express next middleware function for validation error delegation.
   * @returns Void.
   *
   * @example
   * ```ts
   * // PATCH /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * // Body: { "title": "New Title" }
   * router.patch('/:id', updateBookmarkHandler);
   * ```
   */
  function updateBookmarkHandler(req: Request<{ id: string }>, res: Response, next: NextFunction): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const body: unknown = req.body;
    if (typeof body === 'object' && body !== null && 'url' in body && (body as Record<string, unknown>).url !== undefined) {
      res.status(400).json({
        error: 'URL is immutable and cannot be updated',
      });
      return;
    }

    const parseResult = updateBookmarkSchema.safeParse(body);
    if (!parseResult.success) {
      next(parseResult.error);
      return;
    }

    const updated = service.update(id, parseResult.data);
    if (!updated) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(200).json(updated);
  }

  /**
   * Handles DELETE /api/v1/bookmarks/:id - Deletes a bookmark by ID.
   *
   * @param req - Express request containing bookmark ID parameter.
   * @param res - Express response sending 204 No Content or 404 Not Found.
   * @returns Void.
   *
   * @example
   * ```ts
   * // DELETE /api/v1/bookmarks/123e4567-e89b-12d3-a456-426614174000
   * router.delete('/:id', deleteBookmarkHandler);
   * ```
   */
  function deleteBookmarkHandler(req: Request<{ id: string }>, res: Response): void {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(404).json({
        error: 'Not Found',
        message: 'Bookmark not found',
      });
      return;
    }

    const deleted = service.delete(id);
    if (!deleted) {
      res.status(404).json({
        error: 'Not Found',
        message: `Bookmark with id "${id}" not found`,
      });
      return;
    }

    res.status(204).send();
  }

  router.get(['/', '/api/v1/bookmarks'], listBookmarksHandler);
  router.get(['/search', '/api/v1/bookmarks/search'], searchBookmarksHandler);
  router.get(['/:id', '/api/v1/bookmarks/:id'], getBookmarkByIdHandler);
  router.post(['/', '/api/v1/bookmarks'], createBookmarkHandler);
  router.patch(['/:id', '/api/v1/bookmarks/:id'], updateBookmarkHandler);
  router.delete(['/:id', '/api/v1/bookmarks/:id'], deleteBookmarkHandler);

  return router;
}

