import { describe, it, expect, beforeEach } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { Task, Priority } from '../src/queue/types.js';

describe('TaskQueue', () => {
  let queue: TaskQueue;

  const createTask = (
    id: string,
    priority: number = Priority.NORMAL,
    payload: unknown = { action: 'test' }
  ): Task => ({
    id,
    payload,
    priority,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
  });

  beforeEach(() => {
    queue = new TaskQueue();
  });

  describe('empty queue handling', () => {
    it('returns null on dequeue when queue is empty', () => {
      expect(queue.size()).toBe(0);
      expect(queue.isEmpty()).toBe(true);
      expect(queue.dequeue()).toBeNull();
    });

    it('returns null on peek when queue is empty', () => {
      expect(queue.peek()).toBeNull();
    });

    it('returns null after all items are dequeued', () => {
      const task = createTask('t1');
      queue.enqueue(task);
      expect(queue.dequeue()).toEqual(task);
      expect(queue.dequeue()).toBeNull();
      expect(queue.size()).toBe(0);
    });
  });

  describe('enqueue and dequeue order (FIFO within same priority)', () => {
    it('dequeues items in FIFO order when all have identical priority', () => {
      const t1 = createTask('task-1', Priority.NORMAL);
      const t2 = createTask('task-2', Priority.NORMAL);
      const t3 = createTask('task-3', Priority.NORMAL);

      queue.enqueue(t1);
      queue.enqueue(t2);
      queue.enqueue(t3);

      expect(queue.size()).toBe(3);
      expect(queue.dequeue()?.id).toBe('task-1');
      expect(queue.dequeue()?.id).toBe('task-2');
      expect(queue.dequeue()?.id).toBe('task-3');
      expect(queue.dequeue()).toBeNull();
    });

    it('updates size correctly during enqueue and dequeue', () => {
      expect(queue.size()).toBe(0);

      queue.enqueue(createTask('t1'));
      expect(queue.size()).toBe(1);

      queue.enqueue(createTask('t2'));
      expect(queue.size()).toBe(2);

      queue.dequeue();
      expect(queue.size()).toBe(1);

      queue.dequeue();
      expect(queue.size()).toBe(0);
    });
  });

  describe('priority ordering', () => {
    it('dequeues highest priority tasks first regardless of insertion order', () => {
      const low = createTask('task-low', Priority.LOW); // 1
      const normal = createTask('task-normal', Priority.NORMAL); // 5
      const high = createTask('task-high', Priority.HIGH); // 10
      const critical = createTask('task-critical', Priority.CRITICAL); // 20

      // Enqueue in arbitrary order
      queue.enqueue(normal);
      queue.enqueue(low);
      queue.enqueue(critical);
      queue.enqueue(high);

      expect(queue.dequeue()?.id).toBe('task-critical');
      expect(queue.dequeue()?.id).toBe('task-high');
      expect(queue.dequeue()?.id).toBe('task-normal');
      expect(queue.dequeue()?.id).toBe('task-low');
      expect(queue.dequeue()).toBeNull();
    });

    it('preserves FIFO ordering among tasks with the same priority when interleaved', () => {
      const p10_a = createTask('p10-first', 10);
      const p5_a = createTask('p5-first', 5);
      const p10_b = createTask('p10-second', 10);
      const p5_b = createTask('p5-second', 5);
      const p20_a = createTask('p20-only', 20);

      queue.enqueue(p10_a);
      queue.enqueue(p5_a);
      queue.enqueue(p10_b);
      queue.enqueue(p5_b);
      queue.enqueue(p20_a);

      expect(queue.dequeue()?.id).toBe('p20-only');
      expect(queue.dequeue()?.id).toBe('p10-first');
      expect(queue.dequeue()?.id).toBe('p10-second');
      expect(queue.dequeue()?.id).toBe('p5-first');
      expect(queue.dequeue()?.id).toBe('p5-second');
      expect(queue.dequeue()).toBeNull();
    });
  });

  describe('peek', () => {
    it('returns the next task without removing it from the queue', () => {
      const t1 = createTask('t1', Priority.NORMAL);
      const t2 = createTask('t2', Priority.HIGH);

      queue.enqueue(t1);
      queue.enqueue(t2);

      expect(queue.size()).toBe(2);
      expect(queue.peek()?.id).toBe('t2');
      expect(queue.size()).toBe(2);

      // Dequeue confirms t2 was not removed by peek
      expect(queue.dequeue()?.id).toBe('t2');
      expect(queue.peek()?.id).toBe('t1');
      expect(queue.dequeue()?.id).toBe('t1');
      expect(queue.peek()).toBeNull();
    });
  });

  describe('clear and retrieval', () => {
    it('clears all tasks from the queue', () => {
      queue.enqueue(createTask('t1'));
      queue.enqueue(createTask('t2'));
      expect(queue.size()).toBe(2);

      queue.clear();
      expect(queue.size()).toBe(0);
      expect(queue.dequeue()).toBeNull();
      expect(queue.peek()).toBeNull();
    });

    it('retrieves tasks by id and lists all tracked tasks', () => {
      const t1 = createTask('t1', 1);
      const t2 = createTask('t2', 2);
      queue.enqueue(t1);
      queue.enqueue(t2);

      expect(queue.getTask('t1')?.id).toBe('t1');
      expect(queue.getTask('t2')?.id).toBe('t2');
      expect(queue.getTask('t3')).toBeUndefined();

      const all = queue.getAllTasks();
      expect(all).toHaveLength(2);
    });
  });
});

import { randomUUID } from 'node:crypto';
import { Task, TaskResult, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';

export type TaskHandler = (task: Task) => Promise<TaskResult>;

export class Worker {
  public readonly id: string;
  private queue: TaskQueue;
  private handler: TaskHandler;
  private config: WorkerConfig;
  private running = false;
  private currentTask: Task | null = null;
  private currentProcessingPromise: Promise<TaskResult> | null = null;
  private pollTimer: NodeJS.Timeout | null = null;
  private sleepResolve: (() => void) | null = null;

  constructor(queue: TaskQueue, handler: TaskHandler, config: WorkerConfig = {}) {
    this.queue = queue;
    this.handler = handler;
    this.config = config;
    this.id = config.id ?? `worker-${randomUUID()}`;
  }

  public isRunning(): boolean {
    return this.running;
  }

  public isBusy(): boolean {
    return this.currentTask !== null;
  }

  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

  public getConfig(): WorkerConfig {
    return { ...this.config };
  }

  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    void this.poll();
  }

  public async stop(): Promise<void> {
    this.running = false;

    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }

    if (this.sleepResolve) {
      const resolve = this.sleepResolve;
      this.sleepResolve = null;
      resolve();
    }

    if (this.currentProcessingPromise) {
      try {
        await this.currentProcessingPromise;
      } catch {
        // Suppress unhandled rejections during worker shutdown
      }
    }
  }

  public async processNext(): Promise<Task | null> {
    if (this.currentTask) {
      return null;
    }

    const task = this.queue.dequeue();
    if (!task) {
      return null;
    }

    await this.processTask(task);
    return task;
  }

  public async processTask(task: Task): Promise<TaskResult> {
    this.currentTask = task;
    task.status = 'running';
    task.startedAt = new Date();
    task.attempts = (task.attempts || 0) + 1;

    const executionPromise = (async (): Promise<TaskResult> => {
      try {
        const result = await this.handler(task);
        task.result = result;
        task.completedAt = new Date();

        if (result.success) {
          task.status = 'completed';
        } else {
          task.status = 'failed';
        }

        return result;
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        const result: TaskResult = {
          success: false,
          error: errorMsg,
        };
        task.result = result;
        task.status = 'failed';
        task.completedAt = new Date();
        return result;
      } finally {
        this.currentTask = null;
        this.currentProcessingPromise = null;
      }
    })();

    this.currentProcessingPromise = executionPromise;
    return executionPromise;
  }

  private async poll(): Promise<void> {
    const pollInterval = this.config.pollIntervalMs ?? 50;

    while (this.running) {
      try {
        const task = await this.processNext();
        if (!task && this.running) {
          await this.sleep(pollInterval);
        }
      } catch {
        if (this.running) {
          await this.sleep(pollInterval);
        }
      }
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      this.sleepResolve = resolve;
      this.pollTimer = setTimeout(() => {
        this.pollTimer = null;
        this.sleepResolve = null;
        resolve();
      }, ms);
    });
  }
}

import { randomUUID } from 'node:crypto';
import { Task, TaskResult, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';

export type TaskHandler = (task: Task) => Promise<TaskResult>;

export class Worker {
  public readonly id: string;
  private queue: TaskQueue;
  private handler: TaskHandler;
  private config: WorkerConfig;
  private running = false;
  private currentTask: Task | null = null;
  private currentProcessingPromise: Promise<TaskResult> | null = null;
  private pollTimer: NodeJS.Timeout | null = null;
  private sleepResolve: (() => void) | null = null;
  private retryTimers: Set<NodeJS.Timeout> = new Set();

  constructor(queue: TaskQueue, handler: TaskHandler, config: WorkerConfig = {}) {
    this.queue = queue;
    this.handler = handler;
    this.config = config;
    this.id = config.id ?? `worker-${randomUUID()}`;
  }

  public isRunning(): boolean {
    return this.running;
  }

  public isBusy(): boolean {
    return this.currentTask !== null;
  }

  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

  public getConfig(): WorkerConfig {
    return { ...this.config };
  }

  public getPendingRetryCount(): number {
    return this.retryTimers.size;
  }

  public calculateBackoff(attempts: number): number {
    const initial = this.config.initialBackoffMs ?? 100;
    const multiplier = this.config.backoffMultiplier ?? 2;
    const max = this.config.maxBackoffMs ?? 10000;
    const delay = initial * Math.pow(multiplier, Math.max(0, attempts - 1));
    return Math.min(delay, max);
  }

  public scheduleRetry(task: Task): number {
    const delay = this.calculateBackoff(task.attempts);
    const timer = setTimeout(() => {
      this.retryTimers.delete(timer);
      task.status = 'pending';
      this.queue.enqueue(task);
    }, delay);
    this.retryTimers.add(timer);
    return delay;
  }

  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    void this.poll();
  }

  public async stop(): Promise<void> {
    this.running = false;

    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }

    if (this.sleepResolve) {
      const resolve = this.sleepResolve;
      this.sleepResolve = null;
      resolve();
    }

    for (const timer of this.retryTimers) {
      clearTimeout(timer);
    }
    this.retryTimers.clear();

    if (this.currentProcessingPromise) {
      try {
        await this.currentProcessingPromise;
      } catch {
        // Suppress unhandled rejections during worker shutdown
      }
    }
  }

  public async processNext(): Promise<Task | null> {
    if (this.currentTask) {
      return null;
    }

    const task = this.queue.dequeue();
    if (!task) {
      return null;
    }

    await this.processTask(task);
    return task;
  }

  public async processTask(task: Task): Promise<TaskResult> {
    this.currentTask = task;
    task.status = 'running';
    task.startedAt = new Date();
    task.attempts = (task.attempts || 0) + 1;
    if (task.maxAttempts === undefined || task.maxAttempts === null) {
      task.maxAttempts = this.queue.getConfig().defaultMaxAttempts ?? 3;
    }

    const executionPromise = (async (): Promise<TaskResult> => {
      let result: TaskResult;
      try {
        result = await this.handler(task);
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        result = {
          success: false,
          error: errorMsg,
        };
      }

      task.result = result;
      task.completedAt = new Date();

      if (result.success) {
        task.status = 'completed';
      } else {
        task.status = 'failed';
        if (task.attempts < task.maxAttempts) {
          this.scheduleRetry(task);
        }
      }

      return result;
    })();

    this.currentProcessingPromise = executionPromise;
    try {
      return await executionPromise;
    } finally {
      this.currentTask = null;
      this.currentProcessingPromise = null;
    }
  }

  private async poll(): Promise<void> {
    const pollInterval = this.config.pollIntervalMs ?? 50;

    while (this.running) {
      try {
        const task = await this.processNext();
        if (!task && this.running) {
          await this.sleep(pollInterval);
        }
      } catch {
        if (this.running) {
          await this.sleep(pollInterval);
        }
      }
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      this.sleepResolve = resolve;
      this.pollTimer = setTimeout(() => {
        this.pollTimer = null;
        this.sleepResolve = null;
        resolve();
      }, ms);
    });
  }
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { Worker, TaskHandler } from '../src/queue/worker.js';
import { Task, Priority, TaskResult } from '../src/queue/types.js';

describe('Worker', () => {
  let queue: TaskQueue;

  const createTask = (id: string, maxAttempts = 3): Task => ({
    id,
    payload: { action: 'test', id },
    priority: Priority.NORMAL,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts,
  });

  beforeEach(() => {
    queue = new TaskQueue();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe('successful processing', () => {
    it('processes a task successfully and updates task status and timestamps', async () => {
      const handler: TaskHandler = vi.fn().mockResolvedValue({
        success: true,
        data: { message: 'completed successfully' },
      });

      const worker = new Worker(queue, handler, { pollIntervalMs: 20 });
      const task = createTask('task-1');
      queue.enqueue(task);

      const processedTask = await worker.processNext();

      expect(processedTask).not.toBeNull();
      expect(processedTask?.id).toBe('task-1');
      expect(handler).toHaveBeenCalledTimes(1);
      expect(handler).toHaveBeenCalledWith(task);

      expect(task.status).toBe('completed');
      expect(task.attempts).toBe(1);
      expect(task.startedAt).toBeInstanceOf(Date);
      expect(task.completedAt).toBeInstanceOf(Date);
      expect(task.completedAt!.getTime()).toBeGreaterThanOrEqual(task.startedAt!.getTime());
      expect(task.result).toEqual({
        success: true,
        data: { message: 'completed successfully' },
      });
      expect(worker.isBusy()).toBe(false);
      expect(worker.getCurrentTask()).toBeNull();
    });

    it('processes tasks automatically via polling loop', async () => {
      let resolvedTask: Task | null = null;
      const handler: TaskHandler = vi.fn().mockImplementation(async (task: Task) => {
        resolvedTask = task;
        return { success: true };
      });

      const worker = new Worker(queue, handler, { pollIntervalMs: 10 });
      worker.start();
      expect(worker.isRunning()).toBe(true);

      const task = createTask('polled-task');
      queue.enqueue(task);

      // Wait a short time for polling to process
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (resolvedTask) {
            clearInterval(check);
            resolve();
          }
        }, 10);
      });

      expect(resolvedTask).not.toBeNull();
      expect((resolvedTask as unknown as Task).id).toBe('polled-task');
      expect((resolvedTask as unknown as Task).status).toBe('completed');

      await worker.stop();
      expect(worker.isRunning()).toBe(false);
    });
  });

  describe('retry on failure', () => {
    it('schedules retry when handler returns success: false and attempts < maxAttempts', async () => {
      vi.useFakeTimers();

      let attempts = 0;
      const handler: TaskHandler = vi.fn().mockImplementation(async () => {
        attempts++;
        if (attempts === 1) {
          return { success: false, error: 'First attempt failed' };
        }
        return { success: true, data: 'Recovered' };
      });

      const worker = new Worker(queue, handler, {
        initialBackoffMs: 100,
        backoffMultiplier: 2,
      });

      const task = createTask('retry-task', 3);
      queue.enqueue(task);

      // First run: should fail and schedule retry
      await worker.processNext();
      expect(task.status).toBe('failed');
      expect(task.attempts).toBe(1);
      expect(worker.getPendingRetryCount()).toBe(1);
      expect(queue.size()).toBe(0);

      // Fast forward time to trigger retry
      await vi.advanceTimersByTimeAsync(100);

      // Task should now be re-enqueued as pending
      expect(queue.size()).toBe(1);
      expect(task.status).toBe('pending');
      expect(worker.getPendingRetryCount()).toBe(0);

      // Second run: should succeed
      await worker.processNext();
      expect(task.status).toBe('completed');
      expect(task.attempts).toBe(2);
      expect(task.result?.success).toBe(true);

      await worker.stop();
    });

    it('handles thrown exceptions in handler as failures and triggers retry', async () => {
      vi.useFakeTimers();

      const handler: TaskHandler = vi.fn().mockRejectedValue(new Error('Network crash'));
      const worker = new Worker(queue, handler, {
        initialBackoffMs: 50,
      });

      const task = createTask('throw-task', 2);
      queue.enqueue(task);

      await worker.processNext();
      expect(task.status).toBe('failed');
      expect(task.result?.success).toBe(false);
      expect(task.result?.error).toBe('Network crash');
      expect(task.attempts).toBe(1);
      expect(worker.getPendingRetryCount()).toBe(1);

      await vi.advanceTimersByTimeAsync(50);
      expect(queue.size()).toBe(1);
      expect(task.status).toBe('pending');

      await worker.stop();
    });
  });

  describe('give up after maxAttempts', () => {
    it('stops retrying and keeps task in failed state once maxAttempts is reached', async () => {
      vi.useFakeTimers();

      const handler: TaskHandler = vi.fn().mockResolvedValue({
        success: false,
        error: 'Permanent failure',
      });

      const worker = new Worker(queue, handler, {
        initialBackoffMs: 50,
        backoffMultiplier: 2,
      });

      const task = createTask('fail-task', 2);
      queue.enqueue(task);

      // Attempt 1: fails, schedules retry
      await worker.processNext();
      expect(task.attempts).toBe(1);
      expect(worker.getPendingRetryCount()).toBe(1);

      await vi.advanceTimersByTimeAsync(50);
      expect(queue.size()).toBe(1);

      // Attempt 2: fails, reaches maxAttempts (2), no retry scheduled
      await worker.processNext();
      expect(task.attempts).toBe(2);
      expect(task.status).toBe('failed');
      expect(worker.getPendingRetryCount()).toBe(0);
      expect(queue.size()).toBe(0);

      // Advancing time further should not re-enqueue
      await vi.advanceTimersByTimeAsync(1000);
      expect(queue.size()).toBe(0);

      await worker.stop();
    });
  });

  describe('backoff timing', () => {
    it('calculates exponential backoff delay correctly', () => {
      const worker = new Worker(queue, vi.fn(), {
        initialBackoffMs: 100,
        backoffMultiplier: 2,
        maxBackoffMs: 1000,
      });

      // attempt 1 -> 100 * 2^0 = 100
      expect(worker.calculateBackoff(1)).toBe(100);
      // attempt 2 -> 100 * 2^1 = 200
      expect(worker.calculateBackoff(2)).toBe(200);
      // attempt 3 -> 100 * 2^2 = 400
      expect(worker.calculateBackoff(3)).toBe(400);
      // attempt 4 -> 100 * 2^3 = 800
      expect(worker.calculateBackoff(4)).toBe(800);
      // attempt 5 -> 100 * 2^4 = 1600 -> capped at maxBackoffMs (1000)
      expect(worker.calculateBackoff(5)).toBe(1000);
    });

    it('enforces delay timing before re-enqueuing task', async () => {
      vi.useFakeTimers();

      const handler: TaskHandler = vi.fn().mockResolvedValue({
        success: false,
        error: 'fail',
      });

      const worker = new Worker(queue, handler, {
        initialBackoffMs: 200,
        backoffMultiplier: 2,
      });

      const task = createTask('timing-task', 3);
      queue.enqueue(task);

      // Attempt 1: delay should be 200ms
      await worker.processNext();
      expect(queue.size()).toBe(0);

      // Advance by 100ms: not yet re-enqueued
      await vi.advanceTimersByTimeAsync(100);
      expect(queue.size()).toBe(0);

      // Advance remaining 100ms (total 200ms): now re-enqueued
      await vi.advanceTimersByTimeAsync(100);
      expect(queue.size()).toBe(1);

      // Attempt 2: delay should be 400ms (200 * 2^1)
      await worker.processNext();
      expect(queue.size()).toBe(0);

      // Advance 250ms: not yet re-enqueued
      await vi.advanceTimersByTimeAsync(250);
      expect(queue.size()).toBe(0);

      // Advance remaining 150ms (total 400ms): now re-enqueued
      await vi.advanceTimersByTimeAsync(150);
      expect(queue.size()).toBe(1);

      await worker.stop();
    });
  });
});

import { Task, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';
import { Worker, TaskHandler } from './worker.js';

export interface WorkerPoolStats {
  totalWorkers: number;
  activeWorkers: number;
  idleWorkers: number;
  processedCount: number;
  failedCount: number;
}

export class WorkerPool {
  private queue: TaskQueue;
  private handler: TaskHandler;
  private workerConfig: WorkerConfig;
  private workers: Worker[] = [];
  private isStopped = false;
  private workerIdCounter = 0;
  private processedCount = 0;
  private failedCount = 0;

  constructor(queue: TaskQueue, handler: TaskHandler, workerConfig: WorkerConfig = {}) {
    this.queue = queue;
    this.handler = handler;
    this.workerConfig = workerConfig;
  }

  private wrappedHandler: TaskHandler = async (task: Task) => {
    try {
      const result = await this.handler(task);
      if (result.success) {
        this.processedCount++;
      } else {
        this.failedCount++;
      }
      return result;
    } catch (err) {
      this.failedCount++;
      throw err;
    }
  };

  private addWorker(): Worker {
    const workerId = `worker-${++this.workerIdCounter}`;
    const worker = new Worker(this.queue, this.wrappedHandler, {
      ...this.workerConfig,
      id: workerId,
    });
    this.workers.push(worker);
    if (!this.isStopped) {
      worker.start();
    }
    return worker;
  }

  public start(n: number): void {
    if (n < 0) {
      throw new Error('Worker count must be non-negative');
    }
    this.isStopped = false;

    if (this.workers.length > 0) {
      void this.scale(n);
      return;
    }

    for (let i = 0; i < n; i++) {
      this.addWorker();
    }
  }

  public async scale(n: number): Promise<void> {
    const target = Math.max(0, n);

    if (target > this.workers.length) {
      const toAdd = target - this.workers.length;
      for (let i = 0; i < toAdd; i++) {
        this.addWorker();
      }
    } else if (target < this.workers.length) {
      const toRemoveCount = this.workers.length - target;
      const workersToRemove = this.workers.splice(this.workers.length - toRemoveCount, toRemoveCount);
      await Promise.all(workersToRemove.map((w) => w.stop()));
    }
  }

  public async stop(timeoutMs = 30000): Promise<void> {
    this.isStopped = true;
    const stoppingWorkers = this.workers.splice(0, this.workers.length);
    const stopPromise = Promise.all(stoppingWorkers.map((w) => w.stop()));

    if (timeoutMs > 0) {
      let timer: NodeJS.Timeout | undefined;
      const timeoutPromise = new Promise<void>((_, reject) => {
        timer = setTimeout(() => {
          reject(new Error(`WorkerPool stop timed out after ${timeoutMs}ms`));
        }, timeoutMs);
      });

      try {
        await Promise.race([stopPromise, timeoutPromise]);
      } catch {
        // Fallback gracefully on timeout
      } finally {
        if (timer) {
          clearTimeout(timer);
        }
      }
    } else {
      await stopPromise;
    }
  }

  public getStats(): WorkerPoolStats {
    const activeWorkers = this.workers.filter((w) => w.isBusy()).length;
    const idleWorkers = this.workers.filter((w) => !w.isBusy() && w.isRunning()).length;

    return {
      totalWorkers: this.workers.length,
      activeWorkers,
      idleWorkers,
      processedCount: this.processedCount,
      failedCount: this.failedCount,
    };
  }

  public getWorkers(): Worker[] {
    return [...this.workers];
  }

  public getQueue(): TaskQueue {
    return this.queue;
  }

  public isPoolStopped(): boolean {
    return this.isStopped;
  }
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { WorkerPool } from '../src/queue/worker-pool.js';
import { Task, Priority } from '../src/queue/types.js';

describe('WorkerPool', () => {
  let queue: TaskQueue;
  let pool: WorkerPool;

  const createTask = (id: string, priority = Priority.NORMAL): Task => ({
    id,
    payload: { action: 'test', id },
    priority,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
  });

  beforeEach(() => {
    queue = new TaskQueue();
  });

  afterEach(async () => {
    if (pool) {
      await pool.stop();
    }
  });

  describe('lifecycle and scaling', () => {
    it('starts 3 workers, scales up to 5, scales down to 2, and stops all', async () => {
      const handler = vi.fn().mockResolvedValue({ success: true });
      pool = new WorkerPool(queue, handler, { pollIntervalMs: 10 });

      // 1. Start 3 workers
      pool.start(3);
      expect(pool.getStats().totalWorkers).toBe(3);
      expect(pool.getWorkers()).toHaveLength(3);
      expect(pool.getWorkers().every((w) => w.isRunning())).toBe(true);

      // 2. Scale up to 5 workers
      await pool.scale(5);
      expect(pool.getStats().totalWorkers).toBe(5);
      expect(pool.getWorkers()).toHaveLength(5);
      expect(pool.getWorkers().every((w) => w.isRunning())).toBe(true);

      // 3. Scale down to 2 workers
      await pool.scale(2);
      expect(pool.getStats().totalWorkers).toBe(2);
      expect(pool.getWorkers()).toHaveLength(2);
      expect(pool.getWorkers().every((w) => w.isRunning())).toBe(true);

      // 4. Stop all workers
      await pool.stop();
      expect(pool.getStats().totalWorkers).toBe(0);
      expect(pool.getWorkers()).toHaveLength(0);
      expect(pool.isPoolStopped()).toBe(true);
    });
  });

  describe('task processing across worker pool', () => {
    it('processes multiple tasks concurrently across workers and tracks stats', async () => {
      const processedTaskIds: string[] = [];

      const handler = vi.fn().mockImplementation(async (task: Task) => {
        processedTaskIds.push(task.id);
        // Small delay to simulate work
        await new Promise((resolve) => setTimeout(resolve, 20));
        return { success: true };
      });

      pool = new WorkerPool(queue, handler, { pollIntervalMs: 10 });
      pool.start(3);

      const tasks = [
        createTask('t1'),
        createTask('t2'),
        createTask('t3'),
        createTask('t4'),
        createTask('t5'),
      ];

      for (const t of tasks) {
        queue.enqueue(t);
      }

      // Wait until all 5 tasks are processed
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (processedTaskIds.length >= 5) {
            clearInterval(check);
            resolve();
          }
        }, 10);
      });

      expect(processedTaskIds).toHaveLength(5);
      const stats = pool.getStats();
      expect(stats.processedCount).toBe(5);
      expect(stats.failedCount).toBe(0);
      expect(stats.totalWorkers).toBe(3);
    });

    it('tracks failed tasks in pool stats', async () => {
      const handler = vi.fn().mockImplementation(async (task: Task) => {
        if (task.id === 'fail-task') {
          return { success: false, error: 'Expected test failure' };
        }
        return { success: true };
      });

      pool = new WorkerPool(queue, handler, {
        pollIntervalMs: 10,
        initialBackoffMs: 1000, // delay retry so test completes fast
      });
      pool.start(2);

      queue.enqueue(createTask('fail-task'));
      queue.enqueue(createTask('success-task'));

      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          const stats = pool.getStats();
          if (stats.processedCount >= 1 && stats.failedCount >= 1) {
            clearInterval(check);
            resolve();
          }
        }, 10);
      });

      const stats = pool.getStats();
      expect(stats.processedCount).toBe(1);
      expect(stats.failedCount).toBe(1);
    });
  });
});

