import { Task } from './types.js';
import { TaskQueue } from './task-queue.js';

export interface DeadLetterEntry {
  task: Task;
  failedAt: Date;
  lastError: string;
}

export class DeadLetterQueue {
  private queue?: TaskQueue;
  private entries: Map<string, DeadLetterEntry> = new Map();

  constructor(queue?: TaskQueue) {
    this.queue = queue;
  }

  public setQueue(queue: TaskQueue): void {
    this.queue = queue;
  }

  public add(task: Task, lastError?: string): void {
    const errorMsg =
      lastError ??
      task.result?.error ??
      'Task exceeded maximum retry attempts';

    task.status = 'dead_letter';
    this.entries.set(task.id, {
      task,
      failedAt: new Date(),
      lastError: errorMsg,
    });
  }

  public list(): DeadLetterEntry[] {
    return Array.from(this.entries.values());
  }

  public get(taskId: string): DeadLetterEntry | undefined {
    return this.entries.get(taskId);
  }

  public retry(taskId: string, targetQueue?: TaskQueue): Task | null {
    const entry = this.entries.get(taskId);
    if (!entry) {
      return null;
    }

    this.entries.delete(taskId);
    const task = entry.task;
    task.status = 'pending';
    task.attempts = 0;
    task.result = null;

    const queue = targetQueue ?? this.queue;
    if (queue) {
      queue.enqueue(task);
    }

    return task;
  }

  public purge(): number {
    const count = this.entries.size;
    this.entries.clear();
    return count;
  }

  public size(): number {
    return this.entries.size;
  }
}

import { randomUUID } from 'node:crypto';
import { Task, TaskResult, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';
import { DeadLetterQueue } from './dead-letter-queue.js';

export type TaskHandler = (task: Task) => Promise<TaskResult>;

export class Worker {
  public readonly id: string;
  private queue: TaskQueue;
  private handler: TaskHandler;
  private config: WorkerConfig;
  private dlq?: DeadLetterQueue;
  private running = false;
  private currentTask: Task | null = null;
  private currentProcessingPromise: Promise<TaskResult> | null = null;
  private pollTimer: NodeJS.Timeout | null = null;
  private sleepResolve: (() => void) | null = null;
  private retryTimers: Set<NodeJS.Timeout> = new Set();

  constructor(
    queue: TaskQueue,
    handler: TaskHandler,
    config: WorkerConfig = {},
    dlq?: DeadLetterQueue
  ) {
    this.queue = queue;
    this.handler = handler;
    this.config = config;
    this.dlq = dlq;
    this.id = config.id ?? `worker-${randomUUID()}`;
  }

  public setDeadLetterQueue(dlq: DeadLetterQueue): void {
    this.dlq = dlq;
  }

  public getDeadLetterQueue(): DeadLetterQueue | undefined {
    return this.dlq;
  }

  public isRunning(): boolean {
    return this.running;
  }

  public isBusy(): boolean {
    return this.currentTask !== null;
  }

  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

  public getConfig(): WorkerConfig {
    return { ...this.config };
  }

  public getPendingRetryCount(): number {
    return this.retryTimers.size;
  }

  public calculateBackoff(attempts: number): number {
    const initial = this.config.initialBackoffMs ?? 100;
    const multiplier = this.config.backoffMultiplier ?? 2;
    const max = this.config.maxBackoffMs ?? 10000;
    const delay = initial * Math.pow(multiplier, Math.max(0, attempts - 1));
    return Math.min(delay, max);
  }

  public scheduleRetry(task: Task): number {
    const delay = this.calculateBackoff(task.attempts);
    const timer = setTimeout(() => {
      this.retryTimers.delete(timer);
      task.status = 'pending';
      this.queue.enqueue(task);
    }, delay);
    this.retryTimers.add(timer);
    return delay;
  }

  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    void this.poll();
  }

  public async stop(): Promise<void> {
    this.running = false;

    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }

    if (this.sleepResolve) {
      const resolve = this.sleepResolve;
      this.sleepResolve = null;
      resolve();
    }

    for (const timer of this.retryTimers) {
      clearTimeout(timer);
    }
    this.retryTimers.clear();

    if (this.currentProcessingPromise) {
      try {
        await this.currentProcessingPromise;
      } catch {
        // Suppress unhandled rejections during worker shutdown
      }
    }
  }

  public async processNext(): Promise<Task | null> {
    if (this.currentTask) {
      return null;
    }

    const task = this.queue.dequeue();
    if (!task) {
      return null;
    }

    await this.processTask(task);
    return task;
  }

  public async processTask(task: Task): Promise<TaskResult> {
    this.currentTask = task;
    task.status = 'running';
    task.startedAt = new Date();
    task.attempts = (task.attempts || 0) + 1;
    if (task.maxAttempts === undefined || task.maxAttempts === null) {
      task.maxAttempts = this.queue.getConfig().defaultMaxAttempts ?? 3;
    }

    const executionPromise = (async (): Promise<TaskResult> => {
      let result: TaskResult;
      try {
        result = await this.handler(task);
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : String(err);
        result = {
          success: false,
          error: errorMsg,
        };
      }

      task.result = result;
      task.completedAt = new Date();

      if (result.success) {
        task.status = 'completed';
      } else {
        task.status = 'failed';
        if (task.attempts < task.maxAttempts) {
          this.scheduleRetry(task);
        } else if (this.dlq) {
          this.dlq.add(task, result.error);
        }
      }

      return result;
    })();

    this.currentProcessingPromise = executionPromise;
    try {
      return await executionPromise;
    } finally {
      this.currentTask = null;
      this.currentProcessingPromise = null;
    }
  }

  private async poll(): Promise<void> {
    const pollInterval = this.config.pollIntervalMs ?? 50;

    while (this.running) {
      try {
        const task = await this.processNext();
        if (!task && this.running) {
          await this.sleep(pollInterval);
        }
      } catch {
        if (this.running) {
          await this.sleep(pollInterval);
        }
      }
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      this.sleepResolve = resolve;
      this.pollTimer = setTimeout(() => {
        this.pollTimer = null;
        this.sleepResolve = null;
        resolve();
      }, ms);
    });
  }
}

import { Task, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';
import { Worker, TaskHandler } from './worker.js';
import { DeadLetterQueue } from './dead-letter-queue.js';

export interface WorkerPoolStats {
  totalWorkers: number;
  activeWorkers: number;
  idleWorkers: number;
  processedCount: number;
  failedCount: number;
}

export class WorkerPool {
  private queue: TaskQueue;
  private handler: TaskHandler;
  private workerConfig: WorkerConfig;
  private dlq?: DeadLetterQueue;
  private workers: Worker[] = [];
  private isStopped = false;
  private workerIdCounter = 0;
  private processedCount = 0;
  private failedCount = 0;

  constructor(
    queue: TaskQueue,
    handler: TaskHandler,
    workerConfig: WorkerConfig = {},
    dlq?: DeadLetterQueue
  ) {
    this.queue = queue;
    this.handler = handler;
    this.workerConfig = workerConfig;
    this.dlq = dlq;
  }

  public setDeadLetterQueue(dlq: DeadLetterQueue): void {
    this.dlq = dlq;
    for (const worker of this.workers) {
      worker.setDeadLetterQueue(dlq);
    }
  }

  public getDeadLetterQueue(): DeadLetterQueue | undefined {
    return this.dlq;
  }

  private wrappedHandler: TaskHandler = async (task: Task) => {
    try {
      const result = await this.handler(task);
      if (result.success) {
        this.processedCount++;
      } else {
        this.failedCount++;
      }
      return result;
    } catch (err) {
      this.failedCount++;
      throw err;
    }
  };

  private addWorker(): Worker {
    const workerId = `worker-${++this.workerIdCounter}`;
    const worker = new Worker(
      this.queue,
      this.wrappedHandler,
      {
        ...this.workerConfig,
        id: workerId,
      },
      this.dlq
    );
    this.workers.push(worker);
    if (!this.isStopped) {
      worker.start();
    }
    return worker;
  }

  public start(n: number): void {
    if (n < 0) {
      throw new Error('Worker count must be non-negative');
    }
    this.isStopped = false;

    if (this.workers.length > 0) {
      void this.scale(n);
      return;
    }

    for (let i = 0; i < n; i++) {
      this.addWorker();
    }
  }

  public async scale(n: number): Promise<void> {
    const target = Math.max(0, n);

    if (target > this.workers.length) {
      const toAdd = target - this.workers.length;
      for (let i = 0; i < toAdd; i++) {
        this.addWorker();
      }
    } else if (target < this.workers.length) {
      const toRemoveCount = this.workers.length - target;
      const workersToRemove = this.workers.splice(this.workers.length - toRemoveCount, toRemoveCount);
      await Promise.all(workersToRemove.map((w) => w.stop()));
    }
  }

  public async stop(timeoutMs = 30000): Promise<void> {
    this.isStopped = true;
    const stoppingWorkers = this.workers.splice(0, this.workers.length);
    const stopPromise = Promise.all(stoppingWorkers.map((w) => w.stop()));

    if (timeoutMs > 0) {
      let timer: NodeJS.Timeout | undefined;
      const timeoutPromise = new Promise<void>((_, reject) => {
        timer = setTimeout(() => {
          reject(new Error(`WorkerPool stop timed out after ${timeoutMs}ms`));
        }, timeoutMs);
      });

      try {
        await Promise.race([stopPromise, timeoutPromise]);
      } catch {
        // Fallback gracefully on timeout
      } finally {
        if (timer) {
          clearTimeout(timer);
        }
      }
    } else {
      await stopPromise;
    }
  }

  public getStats(): WorkerPoolStats {
    const activeWorkers = this.workers.filter((w) => w.isBusy()).length;
    const idleWorkers = this.workers.filter((w) => !w.isBusy() && w.isRunning()).length;

    return {
      totalWorkers: this.workers.length,
      activeWorkers,
      idleWorkers,
      processedCount: this.processedCount,
      failedCount: this.failedCount,
    };
  }

  public getWorkers(): Worker[] {
    return [...this.workers];
  }

  public getQueue(): TaskQueue {
    return this.queue;
  }

  public isPoolStopped(): boolean {
    return this.isStopped;
  }
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { Worker } from '../src/queue/worker.js';
import { WorkerPool } from '../src/queue/worker-pool.js';
import { DeadLetterQueue } from '../src/queue/dead-letter-queue.js';
import { Task, Priority } from '../src/queue/types.js';

describe('DeadLetterQueue Integration', () => {
  let queue: TaskQueue;
  let dlq: DeadLetterQueue;

  const createTask = (id: string, maxAttempts = 3): Task => ({
    id,
    payload: { action: 'test', id },
    priority: Priority.NORMAL,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts,
  });

  beforeEach(() => {
    queue = new TaskQueue();
    dlq = new DeadLetterQueue(queue);
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  describe('retry and DLQ lifecycle', () => {
    it('moves task to DLQ after failing 3 times, then retry moves it back to main queue', async () => {
      vi.useFakeTimers();

      let runCount = 0;
      const handler = vi.fn().mockImplementation(async () => {
        runCount++;
        if (runCount <= 3) {
          return { success: false, error: 'Database connection failed' };
        }
        return { success: true, data: { processedOnRun: runCount } };
      });

      const worker = new Worker(
        queue,
        handler,
        { initialBackoffMs: 50, backoffMultiplier: 2 },
        dlq
      );

      const task = createTask('dlq-test-task', 3);
      queue.enqueue(task);

      // --- Attempt 1 ---
      await worker.processNext();
      expect(task.attempts).toBe(1);
      expect(task.status).toBe('failed');
      expect(dlq.size()).toBe(0);
      expect(queue.size()).toBe(0);

      // Advance backoff delay (50ms) to re-enqueue
      await vi.advanceTimersByTimeAsync(50);
      expect(queue.size()).toBe(1);
      expect(task.status).toBe('pending');

      // --- Attempt 2 ---
      await worker.processNext();
      expect(task.attempts).toBe(2);
      expect(task.status).toBe('failed');
      expect(dlq.size()).toBe(0);
      expect(queue.size()).toBe(0);

      // Advance backoff delay (100ms) to re-enqueue
      await vi.advanceTimersByTimeAsync(100);
      expect(queue.size()).toBe(1);
      expect(task.status).toBe('pending');

      // --- Attempt 3 (exceeds maxAttempts) ---
      await worker.processNext();
      expect(task.attempts).toBe(3);
      expect(task.status).toBe('dead_letter');

      // Main queue should remain empty and task must appear in DLQ
      expect(queue.size()).toBe(0);
      expect(dlq.size()).toBe(1);

      const dlqEntries = dlq.list();
      expect(dlqEntries).toHaveLength(1);
      expect(dlqEntries[0].task.id).toBe('dlq-test-task');
      expect(dlqEntries[0].lastError).toBe('Database connection failed');
      expect(dlqEntries[0].failedAt).toBeInstanceOf(Date);

      // Advancing time should NOT re-enqueue automatically
      await vi.advanceTimersByTimeAsync(5000);
      expect(queue.size()).toBe(0);
      expect(dlq.size()).toBe(1);

      // --- Manual Retry from DLQ ---
      const retriedTask = dlq.retry('dlq-test-task');
      expect(retriedTask).not.toBeNull();
      expect(retriedTask?.id).toBe('dlq-test-task');

      // DLQ is now empty
      expect(dlq.size()).toBe(0);
      expect(dlq.list()).toHaveLength(0);

      // Main queue contains the retried task in pending state with reset attempts
      expect(queue.size()).toBe(1);
      expect(retriedTask?.status).toBe('pending');
      expect(retriedTask?.attempts).toBe(0);
      expect(queue.peek()?.id).toBe('dlq-test-task');

      // --- Attempt 4 (Success on re-processing) ---
      await worker.processNext();
      expect(retriedTask?.attempts).toBe(1);
      expect(retriedTask?.status).toBe('completed');
      expect(retriedTask?.result?.success).toBe(true);
      expect(queue.size()).toBe(0);
      expect(dlq.size()).toBe(0);

      await worker.stop();
    });
  });

  describe('DLQ management operations', () => {
    it('supports get, purge, and non-existent task retry', () => {
      const task1 = createTask('t1');
      const task2 = createTask('t2');

      dlq.add(task1, 'Error 1');
      dlq.add(task2, 'Error 2');

      expect(dlq.size()).toBe(2);
      expect(dlq.get('t1')?.lastError).toBe('Error 1');
      expect(dlq.get('t2')?.lastError).toBe('Error 2');
      expect(dlq.get('non-existent')).toBeUndefined();

      // Non-existent retry returns null
      expect(dlq.retry('non-existent')).toBeNull();

      // Purge removes all
      const purgedCount = dlq.purge();
      expect(purgedCount).toBe(2);
      expect(dlq.size()).toBe(0);
      expect(dlq.list()).toHaveLength(0);
    });

    it('works seamlessly when wired into WorkerPool', async () => {
      const handler = vi.fn().mockResolvedValue({
        success: false,
        error: 'Pool fatal failure',
      });

      const pool = new WorkerPool(
        queue,
        handler,
        { pollIntervalMs: 10, initialBackoffMs: 10 },
        dlq
      );

      // Task with maxAttempts: 1 fails immediately to DLQ
      const task = createTask('pool-dlq-task', 1);
      queue.enqueue(task);

      pool.start(1);

      // Wait until task reaches DLQ
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (dlq.size() >= 1) {
            clearInterval(check);
            resolve();
          }
        }, 10);
      });

      expect(dlq.size()).toBe(1);
      expect(dlq.list()[0].task.id).toBe('pool-dlq-task');
      expect(dlq.list()[0].lastError).toBe('Pool fatal failure');

      await pool.stop();
    });
  });
});

