import { Router, Request, Response } from 'express';
import { randomUUID } from 'node:crypto';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';

export const defaultQueue = new TaskQueue();
export const defaultDlq = new DeadLetterQueue(defaultQueue);
export const defaultPool = new WorkerPool(
  defaultQueue,
  async (task: Task) => ({ success: true, data: task.payload }),
  { pollIntervalMs: 20 },
  defaultDlq
);

export interface QueueRouterOptions {
  queue?: TaskQueue;
  dlq?: DeadLetterQueue;
  pool?: WorkerPool;
}

export function createQueueRouter(options: QueueRouterOptions = {}): Router {
  const router = Router();
  const queue = options.queue ?? defaultQueue;
  const dlq = options.dlq ?? defaultDlq;
  const pool = options.pool ?? defaultPool;

  // POST /api/v1/tasks — enqueue a task
  router.post(['/tasks', '/api/v1/tasks'], (req: Request, res: Response): void => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const id = typeof body.id === 'string' && body.id.trim().length > 0 ? body.id : randomUUID();
      const priority = typeof body.priority === 'number' ? body.priority : 5;
      const maxAttempts = typeof body.maxAttempts === 'number' && body.maxAttempts > 0 ? body.maxAttempts : 3;
      const payload = body.payload !== undefined ? body.payload : body;

      const task: Task = {
        id,
        payload,
        priority,
        status: 'pending',
        createdAt: new Date(),
        attempts: 0,
        maxAttempts,
        ...(body.scheduledAt ? { scheduledAt: new Date(body.scheduledAt as string | number | Date) } : {}),
        ...(Array.isArray(body.dependsOn) ? { dependsOn: body.dependsOn as string[] } : {}),
      };

      queue.enqueue(task);
      res.status(201).json(task);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  });

  // GET /api/v1/queue/stats — queue depth, active workers, processed count
  router.get(['/queue/stats', '/api/v1/queue/stats'], (_req: Request, res: Response): void => {
    const poolStats = pool ? pool.getStats() : undefined;
    const stats = {
      queueDepth: queue.size(),
      activeWorkers: poolStats?.activeWorkers ?? 0,
      totalWorkers: poolStats?.totalWorkers ?? 0,
      idleWorkers: poolStats?.idleWorkers ?? 0,
      processedCount: poolStats?.processedCount ?? 0,
      failedCount: poolStats?.failedCount ?? 0,
      dlqCount: dlq ? dlq.size() : 0,
    };
    res.status(200).json(stats);
  });

  // POST /api/v1/workers/scale — scale worker count
  router.post(['/workers/scale', '/api/v1/workers/scale'], async (req: Request, res: Response): Promise<void> => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const rawCount = body.count ?? body.workers ?? body.n ?? body.scale;
      const count =
        typeof rawCount === 'number'
          ? rawCount
          : typeof rawCount === 'string'
          ? parseInt(rawCount, 10)
          : undefined;

      if (count === undefined || Number.isNaN(count) || count < 0) {
        res.status(400).json({ error: 'Worker count must be a non-negative number' });
        return;
      }

      if (pool) {
        await pool.scale(count);
        const stats = pool.getStats();
        res.status(200).json({
          message: `Scaled workers to ${count}`,
          count,
          totalWorkers: count,
          stats,
        });
        return;
      }

      res.status(200).json({
        message: `Scaled workers to ${count}`,
        count,
        totalWorkers: count,
      });
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  });

  // GET /api/v1/dlq — list dead-letter tasks
  router.get(['/dlq', '/api/v1/dlq'], (_req: Request, res: Response): void => {
    const entries = dlq ? dlq.list() : [];
    res.status(200).json(entries);
  });

  // POST /api/v1/dlq/:id/retry — retry a DLQ task
  router.post(['/dlq/:id/retry', '/api/v1/dlq/:id/retry'], (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(400).json({ error: 'Task ID is required' });
      return;
    }

    const task = dlq ? dlq.retry(id, queue) : null;
    if (!task) {
      res.status(404).json({ error: 'Task not found in dead-letter queue', id });
      return;
    }

    res.status(200).json({
      message: `Task ${id} retried successfully`,
      task,
      ...task,
    });
  });

  // GET /api/v1/tasks/:id — get task status
  router.get(['/tasks/:id', '/api/v1/tasks/:id'], (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const task = queue.getTask(id) ?? dlq?.get(id)?.task;

    if (!task) {
      res.status(404).json({ error: 'Task not found', id });
      return;
    }

    res.status(200).json(task);
  });

  // GET /api/v1/tasks — list tasks with filtering by status
  router.get(['/tasks', '/api/v1/tasks'], (req: Request, res: Response): void => {
    const { status } = req.query;
    let tasks = queue.getAllTasks();

    if (dlq) {
      const dlqTasks = dlq.list().map((e) => e.task);
      const existingIds = new Set(tasks.map((t) => t.id));
      for (const dt of dlqTasks) {
        if (!existingIds.has(dt.id)) {
          tasks.push(dt);
        }
      }
    }

    if (typeof status === 'string' && status.trim().length > 0) {
      tasks = tasks.filter((t) => t.status === status);
    }

    res.status(200).json(tasks);
  });

  return router;
}

export const queueRouter = createQueueRouter();
export default queueRouter;

import { describe, it, expect, beforeEach, afterAll, vi } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { defaultQueue, defaultDlq, defaultPool } from '../src/routes/queue-api.js';

describe('Queue REST API Integration', () => {
  beforeEach(async () => {
    defaultQueue.clear();
    defaultDlq.purge();
    defaultPool.setHandler(async (task) => ({
      success: true,
      data: { processedPayload: task.payload },
    }));
    await defaultPool.scale(1);
  });

  afterAll(async () => {
    await defaultPool.stop();
  });

  describe('core workflow: enqueue, poll for completion, check stats', () => {
    it('enqueues a task, polls until completion, and verifies stats', async () => {
      // 1. Enqueue a new task
      const enqueueRes = await request(app)
        .post('/api/v1/tasks')
        .send({
          payload: { action: 'process-order', orderId: 12345 },
          priority: 10,
          maxAttempts: 3,
        });

      expect(enqueueRes.status).toBe(201);
      expect(enqueueRes.body.id).toBeDefined();
      expect(enqueueRes.body.status).toBe('pending');
      expect(enqueueRes.body.priority).toBe(10);

      const taskId = enqueueRes.body.id as string;

      // 2. Poll for task completion
      let taskStatus = 'pending';
      let taskResult: unknown = null;

      for (let i = 0; i < 50; i++) {
        const pollRes = await request(app).get(`/api/v1/tasks/${taskId}`);
        expect(pollRes.status).toBe(200);

        if (pollRes.body.status === 'completed') {
          taskStatus = 'completed';
          taskResult = pollRes.body.result;
          break;
        }

        await new Promise((resolve) => setTimeout(resolve, 20));
      }

      expect(taskStatus).toBe('completed');
      expect(taskResult).toEqual({
        success: true,
        data: { processedPayload: { action: 'process-order', orderId: 12345 } },
      });

      // 3. Check queue stats
      const statsRes = await request(app).get('/api/v1/queue/stats');
      expect(statsRes.status).toBe(200);
      expect(statsRes.body.queueDepth).toBe(0);
      expect(statsRes.body.processedCount).toBeGreaterThanOrEqual(1);
      expect(statsRes.body.totalWorkers).toBe(1);
      expect(statsRes.body.activeWorkers).toBe(0);
    });
  });

  describe('task queries and status filtering', () => {
    it('lists tasks and filters by status', async () => {
      // Stop pool temporarily to keep tasks in pending state
      await defaultPool.scale(0);

      await request(app).post('/api/v1/tasks').send({ id: 'pending-1', payload: '1' });
      await request(app).post('/api/v1/tasks').send({ id: 'pending-2', payload: '2' });

      const listRes = await request(app).get('/api/v1/tasks');
      expect(listRes.status).toBe(200);
      expect(listRes.body).toHaveLength(2);

      const filterRes = await request(app).get('/api/v1/tasks?status=pending');
      expect(filterRes.status).toBe(200);
      expect(filterRes.body).toHaveLength(2);

      const emptyFilterRes = await request(app).get('/api/v1/tasks?status=completed');
      expect(emptyFilterRes.status).toBe(200);
      expect(emptyFilterRes.body).toHaveLength(0);
    });

    it('returns 404 for non-existent task id', async () => {
      const res = await request(app).get('/api/v1/tasks/does-not-exist');
      expect(res.status).toBe(404);
      expect(res.body.error).toBe('Task not found');
    });
  });

  describe('workers scaling endpoint', () => {
    it('scales worker count up and down via POST /api/v1/workers/scale', async () => {
      const scaleUp = await request(app)
        .post('/api/v1/workers/scale')
        .send({ count: 4 });

      expect(scaleUp.status).toBe(200);
      expect(scaleUp.body.totalWorkers).toBe(4);

      const statsAfterUp = await request(app).get('/api/v1/queue/stats');
      expect(statsAfterUp.body.totalWorkers).toBe(4);

      const scaleDown = await request(app)
        .post('/api/v1/workers/scale')
        .send({ count: 2 });

      expect(scaleDown.status).toBe(200);
      expect(scaleDown.body.totalWorkers).toBe(2);

      const statsAfterDown = await request(app).get('/api/v1/queue/stats');
      expect(statsAfterDown.body.totalWorkers).toBe(2);
    });

    it('rejects invalid worker counts with 400', async () => {
      const res = await request(app)
        .post('/api/v1/workers/scale')
        .send({ count: -5 });

      expect(res.status).toBe(400);
      expect(res.body.error).toBeDefined();
    });
  });

  describe('DLQ endpoints', () => {
    it('lists dead-letter tasks and retries them via POST /api/v1/dlq/:id/retry', async () => {
      defaultPool.setHandler(async (task) => {
        if (task.id === 'failing-task') {
          return { success: false, error: 'Hard failure' };
        }
        return { success: true };
      });

      // Enqueue task with maxAttempts: 1 so it fails straight to DLQ
      await request(app)
        .post('/api/v1/tasks')
        .send({ id: 'failing-task', payload: 'bad-data', maxAttempts: 1 });

      // Wait for task to land in DLQ
      let inDlq = false;
      for (let i = 0; i < 50; i++) {
        const dlqRes = await request(app).get('/api/v1/dlq');
        if (dlqRes.body.some((e: { task: { id: string } }) => e.task.id === 'failing-task')) {
          inDlq = true;
          break;
        }
        await new Promise((resolve) => setTimeout(resolve, 20));
      }
      expect(inDlq).toBe(true);

      // Verify list endpoint contains failure details
      const dlqListRes = await request(app).get('/api/v1/dlq');
      expect(dlqListRes.status).toBe(200);
      expect(dlqListRes.body).toHaveLength(1);
      expect(dlqListRes.body[0].task.id).toBe('failing-task');
      expect(dlqListRes.body[0].lastError).toBe('Hard failure');

      // Change handler so retry succeeds
      defaultPool.setHandler(async () => ({ success: true, data: 'recovered' }));

      // Retry the task via DLQ API
      const retryRes = await request(app).post('/api/v1/dlq/failing-task/retry');
      expect(retryRes.status).toBe(200);

      // DLQ should now be empty
      const dlqEmptyRes = await request(app).get('/api/v1/dlq');
      expect(dlqEmptyRes.body).toHaveLength(0);

      // Task should now be re-processed and complete
      let completedAfterRetry = false;
      for (let i = 0; i < 50; i++) {
        const poll = await request(app).get('/api/v1/tasks/failing-task');
        if (poll.body.status === 'completed') {
          completedAfterRetry = true;
          break;
        }
        await new Promise((resolve) => setTimeout(resolve, 20));
      }
      expect(completedAfterRetry).toBe(true);
    });

    it('returns 404 when retrying non-existent DLQ task', async () => {
      const res = await request(app).post('/api/v1/dlq/not-in-dlq/retry');
      expect(res.status).toBe(404);
      expect(res.body.error).toContain('not found in dead-letter queue');
    });
  });
});

import { Task } from './types.js';
import { TaskQueue } from './task-queue.js';

export interface SchedulerConfig {
  checkIntervalMs?: number;
}

export class Scheduler {
  private queue: TaskQueue;
  private config: SchedulerConfig;
  private scheduledTasks: Map<string, Task> = new Map();
  private timer: NodeJS.Timeout | null = null;
  private running = false;

  constructor(queue: TaskQueue, config: SchedulerConfig = {}) {
    this.queue = queue;
    this.config = config;
  }

  public schedule(task: Task): void {
    task.status = 'scheduled';
    this.scheduledTasks.set(task.id, task);
  }

  public getScheduledTasks(): Task[] {
    return Array.from(this.scheduledTasks.values());
  }

  public getTask(id: string): Task | undefined {
    return this.scheduledTasks.get(id);
  }

  public cancel(id: string): boolean {
    return this.scheduledTasks.delete(id);
  }

  public checkDueTasks(now: Date = new Date()): Task[] {
    const dueTasks: Task[] = [];
    const currentTime = now.getTime();

    for (const [id, task] of this.scheduledTasks.entries()) {
      const scheduledTime = task.scheduledAt
        ? new Date(task.scheduledAt).getTime()
        : 0;

      if (scheduledTime <= currentTime) {
        this.scheduledTasks.delete(id);
        task.status = 'pending';
        this.queue.enqueue(task);
        dueTasks.push(task);
      }
    }

    return dueTasks;
  }

  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    const interval = this.config.checkIntervalMs ?? 1000;
    this.timer = setInterval(() => {
      this.checkDueTasks();
    }, interval);
  }

  public stop(): void {
    this.running = false;
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  public isRunning(): boolean {
    return this.running;
  }

  public size(): number {
    return this.scheduledTasks.size;
  }

  public clear(): void {
    this.scheduledTasks.clear();
  }
}

import { Router, Request, Response } from 'express';
import { randomUUID } from 'node:crypto';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';
import { Scheduler } from '../queue/scheduler.js';

export const defaultQueue = new TaskQueue();
export const defaultDlq = new DeadLetterQueue(defaultQueue);
export const defaultPool = new WorkerPool(
  defaultQueue,
  async (task: Task) => ({ success: true, data: task.payload }),
  { pollIntervalMs: 20 },
  defaultDlq
);
export const defaultScheduler = new Scheduler(defaultQueue, { checkIntervalMs: 1000 });

export interface QueueRouterOptions {
  queue?: TaskQueue;
  dlq?: DeadLetterQueue;
  pool?: WorkerPool;
  scheduler?: Scheduler;
}

export function createQueueRouter(options: QueueRouterOptions = {}): Router {
  const router = Router();
  const queue = options.queue ?? defaultQueue;
  const dlq = options.dlq ?? defaultDlq;
  const pool = options.pool ?? defaultPool;
  const scheduler = options.scheduler ?? defaultScheduler;

  // POST /api/v1/tasks — enqueue a task
  router.post(['/tasks', '/api/v1/tasks'], (req: Request, res: Response): void => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const id = typeof body.id === 'string' && body.id.trim().length > 0 ? body.id : randomUUID();
      const priority = typeof body.priority === 'number' ? body.priority : 5;
      const maxAttempts = typeof body.maxAttempts === 'number' && body.maxAttempts > 0 ? body.maxAttempts : 3;
      const payload = body.payload !== undefined ? body.payload : body;

      let scheduledAt: Date | undefined;
      if (body.scheduledAt !== undefined && body.scheduledAt !== null) {
        scheduledAt = new Date(body.scheduledAt as string | number | Date);
        if (Number.isNaN(scheduledAt.getTime())) {
          res.status(400).json({ error: 'Invalid scheduledAt timestamp' });
          return;
        }
      }

      const isFuture = scheduledAt !== undefined && scheduledAt.getTime() > Date.now();

      const task: Task = {
        id,
        payload,
        priority,
        status: isFuture ? 'scheduled' : 'pending',
        createdAt: new Date(),
        attempts: 0,
        maxAttempts,
        ...(scheduledAt ? { scheduledAt } : {}),
        ...(Array.isArray(body.dependsOn) ? { dependsOn: body.dependsOn as string[] } : {}),
      };

      if (isFuture) {
        if (scheduler) {
          scheduler.schedule(task);
        } else {
          const delay = scheduledAt!.getTime() - Date.now();
          setTimeout(() => {
            task.status = 'pending';
            queue.enqueue(task);
          }, delay);
        }
      } else {
        queue.enqueue(task);
      }

      res.status(201).json(task);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  });

  // GET /api/v1/queue/stats — queue depth, active workers, processed count
  router.get(['/queue/stats', '/api/v1/queue/stats'], (_req: Request, res: Response): void => {
    const poolStats = pool ? pool.getStats() : undefined;
    const stats = {
      queueDepth: queue.size(),
      activeWorkers: poolStats?.activeWorkers ?? 0,
      totalWorkers: poolStats?.totalWorkers ?? 0,
      idleWorkers: poolStats?.idleWorkers ?? 0,
      processedCount: poolStats?.processedCount ?? 0,
      failedCount: poolStats?.failedCount ?? 0,
      dlqCount: dlq ? dlq.size() : 0,
      scheduledCount: scheduler ? scheduler.size() : 0,
    };
    res.status(200).json(stats);
  });

  // POST /api/v1/workers/scale — scale worker count
  router.post(['/workers/scale', '/api/v1/workers/scale'], async (req: Request, res: Response): Promise<void> => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const rawCount = body.count ?? body.workers ?? body.n ?? body.scale;
      const count =
        typeof rawCount === 'number'
          ? rawCount
          : typeof rawCount === 'string'
          ? parseInt(rawCount, 10)
          : undefined;

      if (count === undefined || Number.isNaN(count) || count < 0) {
        res.status(400).json({ error: 'Worker count must be a non-negative number' });
        return;
      }

      if (pool) {
        await pool.scale(count);
        const stats = pool.getStats();
        res.status(200).json({
          message: `Scaled workers to ${count}`,
          count,
          totalWorkers: count,
          stats,
        });
        return;
      }

      res.status(200).json({
        message: `Scaled workers to ${count}`,
        count,
        totalWorkers: count,
      });
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  });

  // GET /api/v1/dlq — list dead-letter tasks
  router.get(['/dlq', '/api/v1/dlq'], (_req: Request, res: Response): void => {
    const entries = dlq ? dlq.list() : [];
    res.status(200).json(entries);
  });

  // POST /api/v1/dlq/:id/retry — retry a DLQ task
  router.post(['/dlq/:id/retry', '/api/v1/dlq/:id/retry'], (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(400).json({ error: 'Task ID is required' });
      return;
    }

    const task = dlq ? dlq.retry(id, queue) : null;
    if (!task) {
      res.status(404).json({ error: 'Task not found in dead-letter queue', id });
      return;
    }

    res.status(200).json({
      message: `Task ${id} retried successfully`,
      task,
      ...task,
    });
  });

  // GET /api/v1/tasks/:id — get task status
  router.get(['/tasks/:id', '/api/v1/tasks/:id'], (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const task = queue.getTask(id) ?? dlq?.get(id)?.task ?? scheduler?.getTask(id);

    if (!task) {
      res.status(404).json({ error: 'Task not found', id });
      return;
    }

    res.status(200).json(task);
  });

  // GET /api/v1/tasks — list tasks with filtering by status
  router.get(['/tasks', '/api/v1/tasks'], (req: Request, res: Response): void => {
    const { status } = req.query;
    let tasks = queue.getAllTasks();
    const existingIds = new Set(tasks.map((t) => t.id));

    if (dlq) {
      const dlqTasks = dlq.list().map((e) => e.task);
      for (const dt of dlqTasks) {
        if (!existingIds.has(dt.id)) {
          tasks.push(dt);
          existingIds.add(dt.id);
        }
      }
    }

    if (scheduler) {
      const scheduledTasks = scheduler.getScheduledTasks();
      for (const st of scheduledTasks) {
        if (!existingIds.has(st.id)) {
          tasks.push(st);
          existingIds.add(st.id);
        }
      }
    }

    if (typeof status === 'string' && status.trim().length > 0) {
      tasks = tasks.filter((t) => t.status === status);
    }

    res.status(200).json(tasks);
  });

  return router;
}

