import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { Scheduler } from '../src/queue/scheduler.js';
import { Task, Priority } from '../src/queue/types.js';

describe('Scheduler', () => {
  let queue: TaskQueue;
  let scheduler: Scheduler;

  const createTask = (id: string, scheduledAt?: Date, priority = Priority.NORMAL): Task => ({
    id,
    payload: { action: 'run', id },
    priority,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
    scheduledAt,
  });

  beforeEach(() => {
    vi.useFakeTimers();
    queue = new TaskQueue();
    scheduler = new Scheduler(queue, { checkIntervalMs: 1000 });
  });

  afterEach(() => {
    scheduler.stop();
    vi.useRealTimers();
  });

  describe('future task scheduling', () => {
    it('schedules a task 2 seconds in the future, verifies it is not immediately dequeued, and verifies it appears after 2 seconds', async () => {
      scheduler.start();
      expect(scheduler.isRunning()).toBe(true);

      const scheduledTime = new Date(Date.now() + 2000);
      const task = createTask('future-task', scheduledTime);

      // Schedule the task
      scheduler.schedule(task);

      // 1. Verify it is held in scheduler and marked 'scheduled'
      expect(task.status).toBe('scheduled');
      expect(scheduler.size()).toBe(1);
      expect(scheduler.getTask('future-task')).toBeDefined();

      // 2. Verify it is NOT immediately in the main queue
      expect(queue.size()).toBe(0);
      expect(queue.dequeue()).toBeNull();

      // 3. Advance by 1 second: still not due, must not be dequeued
      await vi.advanceTimersByTimeAsync(1000);
      expect(queue.size()).toBe(0);
      expect(queue.dequeue()).toBeNull();
      expect(task.status).toBe('scheduled');
      expect(scheduler.size()).toBe(1);

      // 4. Advance another 1 second (total 2 seconds): task is now due
      await vi.advanceTimersByTimeAsync(1000);

      // Task must now be moved to the main queue
      expect(scheduler.size()).toBe(0);
      expect(queue.size()).toBe(1);

      const dequeuedTask = queue.dequeue();
      expect(dequeuedTask).not.toBeNull();
      expect(dequeuedTask?.id).toBe('future-task');
      expect(dequeuedTask?.status).toBe('pending');
      expect(queue.size()).toBe(0);
    });

    it('dispatches multiple scheduled tasks according to their due times and respects priority', async () => {
      scheduler.start();

      const taskAt1sLow = createTask('task-1s-low', new Date(Date.now() + 1000), Priority.LOW); // priority 1
      const taskAt1sHigh = createTask('task-1s-high', new Date(Date.now() + 1000), Priority.HIGH); // priority 10
      const taskAt2s = createTask('task-2s', new Date(Date.now() + 2000), Priority.CRITICAL); // priority 20

      scheduler.schedule(taskAt1sLow);
      scheduler.schedule(taskAt1sHigh);
      scheduler.schedule(taskAt2s);

      expect(queue.size()).toBe(0);

      // Advance by 1s: both 1s tasks should enter the queue and be ordered by priority
      await vi.advanceTimersByTimeAsync(1000);
      expect(queue.size()).toBe(2);

      // High priority task should be dequeued before low priority task
      expect(queue.dequeue()?.id).toBe('task-1s-high');
      expect(queue.dequeue()?.id).toBe('task-1s-low');
      expect(queue.size()).toBe(0);

      // Advance to 2s: taskAt2s should now enter the queue
      await vi.advanceTimersByTimeAsync(1000);
      expect(queue.size()).toBe(1);
      expect(queue.dequeue()?.id).toBe('task-2s');
      expect(queue.size()).toBe(0);
    });

    it('cancels a scheduled task so it never enters the main queue', async () => {
      scheduler.start();

      const task = createTask('cancel-task', new Date(Date.now() + 2000));
      scheduler.schedule(task);
      expect(scheduler.size()).toBe(1);

      const cancelled = scheduler.cancel('cancel-task');
      expect(cancelled).toBe(true);
      expect(scheduler.size()).toBe(0);

      // Advance time past due date
      await vi.advanceTimersByTimeAsync(3000);
      expect(queue.size()).toBe(0);
      expect(queue.dequeue()).toBeNull();
    });
  });
});

