import { TaskQueue } from '../src/queue/task-queue.js';
import { Worker } from '../src/queue/worker.js';
import { Task, Priority } from '../src/queue/types.js';

describe('Task Dependencies', () => {
  let queue: TaskQueue;

  const createTask = (
    id: string,
    dependsOn?: string[],
    priority: number = Priority.NORMAL
  ): Task => ({
    id,
    payload: { action: 'test', id },
    priority,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
    dependsOn,
  });

  beforeEach(() => {
    queue = new TaskQueue();
  });

  describe('direct dependency resolution', () => {
    it('task B depends on task A, B is not dequeued until A completes', () => {
      // Task B has higher priority (10) than Task A (5), but depends on Task A
      const taskA = createTask('task-A', undefined, Priority.NORMAL); // priority 5
      const taskB = createTask('task-B', ['task-A'], Priority.HIGH); // priority 10

      // Enqueue B first, then A
      queue.enqueue(taskB);
      queue.enqueue(taskA);

      expect(queue.size()).toBe(2);

      // 1. First dequeue must return Task A, NOT Task B (even though B has higher priority)
      const first = queue.dequeue();
      expect(first).not.toBeNull();
      expect(first?.id).toBe('task-A');

      // 2. While Task A has not completed, Task B cannot be dequeued
      expect(queue.size()).toBe(1);
      expect(queue.peek()).toBeNull();
      expect(queue.dequeue()).toBeNull();

      // 3. Mark Task A as completed
      taskA.status = 'completed';

      // 4. Now Task B is ready and can be dequeued
      expect(queue.peek()?.id).toBe('task-B');
      const second = queue.dequeue();
      expect(second).not.toBeNull();
      expect(second?.id).toBe('task-B');
      expect(queue.size()).toBe(0);
    });

    it('handles multiple dependencies: task C depends on both A and B', () => {
      const taskA = createTask('task-A');
      const taskB = createTask('task-B');
      const taskC = createTask('task-C', ['task-A', 'task-B'], Priority.CRITICAL);

      queue.enqueue(taskC);
      queue.enqueue(taskA);
      queue.enqueue(taskB);

      // Task A is dequeued first
      const first = queue.dequeue();
      expect(first?.id).toBe('task-A');

      // Task C still cannot be dequeued because B is incomplete
      expect(queue.dequeue()?.id).toBe('task-B');

      // Now only C remains, but A and B are not yet marked completed
      expect(queue.dequeue()).toBeNull();

      // Complete A only: C still blocked
      taskA.status = 'completed';
      expect(queue.dequeue()).toBeNull();

      // Complete B: C is unblocked
      taskB.status = 'completed';
      expect(queue.dequeue()?.id).toBe('task-C');
    });

    it('handles dependency chains: C depends on B, B depends on A', () => {
      const taskA = createTask('task-A');
      const taskB = createTask('task-B', ['task-A']);
      const taskC = createTask('task-C', ['task-B']);

      // Enqueue in reverse order
      queue.enqueue(taskC);
      queue.enqueue(taskB);
      queue.enqueue(taskA);

      // Only A is ready
      expect(queue.dequeue()?.id).toBe('task-A');
      expect(queue.dequeue()).toBeNull();

      // Complete A: now B is ready
      taskA.status = 'completed';
      expect(queue.dequeue()?.id).toBe('task-B');
      expect(queue.dequeue()).toBeNull();

      // Complete B: now C is ready
      taskB.status = 'completed';
      expect(queue.dequeue()?.id).toBe('task-C');
      expect(queue.dequeue()).toBeNull();
    });
  });

  describe('Worker integration with dependencies', () => {
    it('executes tasks in dependency order with worker', async () => {
      const executionOrder: string[] = [];

      const handler = async (task: Task) => {
        executionOrder.push(task.id);
        return { success: true };
      };

      const worker = new Worker(queue, handler, { pollIntervalMs: 10 });

      const taskA = createTask('task-A', undefined, Priority.LOW);
      const taskB = createTask('task-B', ['task-A'], Priority.HIGH);

      queue.enqueue(taskB);
      queue.enqueue(taskA);

      worker.start();

      // Wait until both tasks are executed
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (executionOrder.length >= 2) {
            clearInterval(check);
            resolve();
          }
        }, 10);
      });

      await worker.stop();

      // Confirms Task A was executed first, then Task B
      expect(executionOrder).toEqual(['task-A', 'task-B']);
      expect(taskA.status).toBe('completed');
      expect(taskB.status).toBe('completed');
    });
  });
});

import { TaskQueue } from './task-queue.js';

export interface QueueDepthSample {
  timestamp: number;
  depth: number;
}

export interface MetricsData {
  tasksProcessed: number;
  tasksFailed: number;
  avgProcessingTimeMs: number;
  queueDepthOverTime: QueueDepthSample[];
}

export class MetricsCollector {
  private queue: TaskQueue;
  private tasksProcessed = 0;
  private tasksFailed = 0;
  private totalProcessingTimeMs = 0;
  private queueDepthOverTime: QueueDepthSample[] = [];
  private sampleTimer: NodeJS.Timeout | null = null;
  private maxSamples: number;

  constructor(queue: TaskQueue, options: { maxSamples?: number } = {}) {
    this.queue = queue;
    this.maxSamples = options.maxSamples ?? 3600;
  }

  public recordTaskCompleted(durationMs: number): void {
    this.tasksProcessed++;
    this.totalProcessingTimeMs += durationMs;
  }

  public recordTaskFailed(durationMs = 0): void {
    this.tasksFailed++;
    this.totalProcessingTimeMs += durationMs;
  }

  public sampleQueueDepth(depth?: number): void {
    const currentDepth = depth !== undefined ? depth : this.queue.size();
    this.queueDepthOverTime.push({
      timestamp: Date.now(),
      depth: currentDepth,
    });
    if (this.queueDepthOverTime.length > this.maxSamples) {
      this.queueDepthOverTime.shift();
    }
  }

  public start(intervalMs = 1000): void {
    if (this.sampleTimer) {
      return;
    }
    this.sampleQueueDepth();
    this.sampleTimer = setInterval(() => {
      this.sampleQueueDepth();
    }, intervalMs);

    if (typeof this.sampleTimer.unref === 'function') {
      this.sampleTimer.unref();
    }
  }

  public stop(): void {
    if (this.sampleTimer) {
      clearInterval(this.sampleTimer);
      this.sampleTimer = null;
    }
  }

  public getMetrics(): MetricsData {
    const avg =
      this.tasksProcessed > 0
        ? Math.round((this.totalProcessingTimeMs / this.tasksProcessed) * 100) / 100
        : 0;

    return {
      tasksProcessed: this.tasksProcessed,
      tasksFailed: this.tasksFailed,
      avgProcessingTimeMs: avg,
      queueDepthOverTime: [...this.queueDepthOverTime],
    };
  }

  public reset(): void {
    this.tasksProcessed = 0;
    this.tasksFailed = 0;
    this.totalProcessingTimeMs = 0;
    this.queueDepthOverTime = [];
  }
}

