import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import request from 'supertest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { Worker } from '../src/queue/worker.js';
import { MetricsCollector } from '../src/queue/metrics.js';
import { Task, Priority } from '../src/queue/types.js';
import { app } from '../src/app.js';
import { defaultMetrics, defaultQueue } from '../src/routes/queue-api.js';

describe('Metrics', () => {
  let queue: TaskQueue;
  let metrics: MetricsCollector;

  const createTask = (id: string): Task => ({
    id,
    payload: { action: 'compute', id },
    priority: Priority.NORMAL,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
  });

  beforeEach(() => {
    queue = new TaskQueue();
    metrics = new MetricsCollector(queue);
  });

  afterEach(() => {
    metrics.stop();
    vi.useRealTimers();
  });

  describe('task processing metrics', () => {
    it('processes 5 tasks, verifies counts and avg time via worker integration', async () => {
      const taskDurationsMs = [10, 20, 30, 40, 50]; // average is 30ms
      let taskIndex = 0;

      const handler = async (_task: Task) => {
        const delay = taskDurationsMs[taskIndex++] ?? 10;
        await new Promise((resolve) => setTimeout(resolve, delay));
        return { success: true };
      };

      const worker = new Worker(queue, handler);
      worker.setMetrics(metrics);

      // Enqueue 5 tasks
      for (let i = 1; i <= 5; i++) {
        queue.enqueue(createTask(`task-${i}`));
      }

      // Process all 5 tasks
      for (let i = 0; i < 5; i++) {
        const processed = await worker.processNext();
        expect(processed).not.toBeNull();
      }

      const data = metrics.getMetrics();

      // 1. Verify counts
      expect(data.tasksProcessed).toBe(5);
      expect(data.tasksFailed).toBe(0);

      // 2. Verify average processing time is approximately 30ms (allowing small scheduler margin)
      expect(data.avgProcessingTimeMs).toBeGreaterThanOrEqual(25);
      expect(data.avgProcessingTimeMs).toBeLessThanOrEqual(60);
    });

    it('calculates exact average processing time across 5 tasks with explicit durations', () => {
      const durations = [100, 200, 300, 400, 500]; // sum = 1500, avg = 300

      for (const d of durations) {
        metrics.recordTaskCompleted(d);
      }

      const data = metrics.getMetrics();
      expect(data.tasksProcessed).toBe(5);
      expect(data.tasksFailed).toBe(0);
      expect(data.avgProcessingTimeMs).toBe(300);
    });

    it('tracks failed tasks and recalculates average accurately', () => {
      metrics.recordTaskCompleted(100);
      metrics.recordTaskCompleted(200);
      metrics.recordTaskFailed(50);

      const data = metrics.getMetrics();
      expect(data.tasksProcessed).toBe(2);
      expect(data.tasksFailed).toBe(1);
      // avg over processed tasks: (100 + 200 + 50) / 2 = 175
      expect(data.avgProcessingTimeMs).toBe(175);
    });
  });

  describe('queue depth sampling over time', () => {
    it('samples queue depth every second', async () => {
      vi.useFakeTimers();

      queue.enqueue(createTask('t1'));
      queue.enqueue(createTask('t2'));

      metrics.start(1000);

      // Immediate sample at start
      expect(metrics.getMetrics().queueDepthOverTime).toHaveLength(1);
      expect(metrics.getMetrics().queueDepthOverTime[0].depth).toBe(2);

      // Advance 1s
      await vi.advanceTimersByTimeAsync(1000);
      expect(metrics.getMetrics().queueDepthOverTime).toHaveLength(2);

      // Dequeue 1 task
      queue.dequeue();

      // Advance another 1s
      await vi.advanceTimersByTimeAsync(1000);
      const samples = metrics.getMetrics().queueDepthOverTime;
      expect(samples).toHaveLength(3);
      expect(samples[2].depth).toBe(1);
    });
  });

  describe('GET /api/v1/metrics endpoint', () => {
    it('exposes metrics via REST endpoint', async () => {
      defaultMetrics.reset();
      defaultMetrics.recordTaskCompleted(120);

      const res = await request(app).get('/api/v1/metrics');
      expect(res.status).toBe(200);
      expect(res.body.tasksProcessed).toBe(1);
      expect(res.body.avgProcessingTimeMs).toBe(120);
      expect(Array.isArray(res.body.queueDepthOverTime)).toBe(true);
    });
  });
});

import { Request, Response, NextFunction } from 'express';

export interface RateLimiterOptions {
  windowMs?: number;
  max?: number;
  message?: string;
}

export interface RateLimiterMiddleware {
  (req: Request, res: Response, next: NextFunction): void;
  reset(): void;
  getHits(ip: string): number;
}

export function createRateLimiter(options: RateLimiterOptions = {}): RateLimiterMiddleware {
  const windowMs = options.windowMs ?? 60 * 1000; // 1 minute default
  const max = options.max ?? 100; // 100 requests per minute default
  const message =
    options.message ??
    `Rate limit exceeded. Max ${max} requests per minute.`;

  const ipRequests = new Map<string, number[]>();

  const middleware = (req: Request, res: Response, next: NextFunction): void => {
    const rawIp =
      req.ip ||
      req.socket.remoteAddress ||
      req.headers['x-forwarded-for'] ||
      '127.0.0.1';

    const ip =
      typeof rawIp === 'string'
        ? rawIp.split(',')[0].trim()
        : Array.isArray(rawIp)
        ? rawIp[0].trim()
        : '127.0.0.1';

    const now = Date.now();
    const windowStart = now - windowMs;

    let timestamps = ipRequests.get(ip) ?? [];
    // Filter out timestamps outside the sliding window
    timestamps = timestamps.filter((t) => t > windowStart);

    if (timestamps.length >= max) {
      const oldestTimestamp = timestamps[0];
      const resetTime = oldestTimestamp + windowMs;
      const retryAfterSeconds = Math.max(1, Math.ceil((resetTime - now) / 1000));

      res.setHeader('Retry-After', String(retryAfterSeconds));
      res.setHeader('X-RateLimit-Limit', String(max));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetTime / 1000)));

      res.status(429).json({
        error: 'Too Many Requests',
        message,
        retryAfter: retryAfterSeconds,
      });
      return;
    }

    timestamps.push(now);
    ipRequests.set(ip, timestamps);

    res.setHeader('X-RateLimit-Limit', String(max));
    res.setHeader('X-RateLimit-Remaining', String(max - timestamps.length));

    next();
  };

  middleware.reset = (): void => {
    ipRequests.clear();
  };

  middleware.getHits = (ip: string): number => {
    const now = Date.now();
    const timestamps = ipRequests.get(ip) ?? [];
    return timestamps.filter((t) => t > now - windowMs).length;
  };

  return middleware;
}

export const rateLimiter = createRateLimiter();
export default rateLimiter;

