import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import request from 'supertest';
import express, { Request, Response } from 'express';
import { app } from '../src/app.js';
import { rateLimiter, createRateLimiter } from '../src/middleware/rate-limiter.js';

describe('Rate Limiter', () => {
  beforeEach(() => {
    rateLimiter.reset();
  });

  afterEach(() => {
    rateLimiter.reset();
    vi.useRealTimers();
  });

  describe('Express app integration (100 req/min limit)', () => {
    it('allows requests up to 100 and returns 429 on the 101st request', async () => {
      // Send 100 requests from client IP
      for (let i = 0; i < 100; i++) {
        const res = await request(app)
          .get('/api/v1/queue/stats')
          .set('X-Forwarded-For', '10.0.0.1');

        expect(res.status).toBe(200);
        expect(res.headers['x-ratelimit-limit']).toBe('100');
        expect(res.headers['x-ratelimit-remaining']).toBe(String(100 - (i + 1)));
      }

      // 101st request must be blocked with 429
      const blockedRes = await request(app)
        .get('/api/v1/queue/stats')
        .set('X-Forwarded-For', '10.0.0.1');

      expect(blockedRes.status).toBe(429);
      expect(blockedRes.body.error).toBe('Too Many Requests');
      expect(blockedRes.body.message).toContain('Max 100 requests per minute');
      expect(blockedRes.headers['retry-after']).toBeDefined();
      expect(blockedRes.headers['x-ratelimit-remaining']).toBe('0');
    });

    it('enforces rate limits per IP independently', async () => {
      // Exhaust quota for IP A
      for (let i = 0; i < 100; i++) {
        await request(app)
          .get('/api/v1/queue/stats')
          .set('X-Forwarded-For', '192.168.1.10');
      }

      // IP A is blocked
      const blockedA = await request(app)
        .get('/api/v1/queue/stats')
        .set('X-Forwarded-For', '192.168.1.10');
      expect(blockedA.status).toBe(429);

      // IP B is still allowed
      const allowedB = await request(app)
        .get('/api/v1/queue/stats')
        .set('X-Forwarded-For', '192.168.1.20');
      expect(allowedB.status).toBe(200);
      expect(allowedB.headers['x-ratelimit-remaining']).toBe('99');
    });
  });

  describe('custom configuration and sliding window reset', () => {
    it('blocks after custom max and resets after windowMs', async () => {
      const customLimiter = createRateLimiter({
        windowMs: 500,
        max: 3,
      });

      const testApp = express();
      testApp.use(customLimiter);
      testApp.get('/test', (_req, res) => {
        res.json({ ok: true });
      });

      // 3 requests allowed
      for (let i = 0; i < 3; i++) {
        const res = await request(testApp).get('/test');
        expect(res.status).toBe(200);
      }

      // 4th request blocked
      const blocked = await request(testApp).get('/test');
      expect(blocked.status).toBe(429);

      // Wait for windowMs (500ms) to pass
      await new Promise((resolve) => setTimeout(resolve, 550));

      // Allowed again after window resets
      const afterReset = await request(testApp).get('/test');
      expect(afterReset.status).toBe(200);
    });

    it('reset() clears active IP tracking counters', async () => {
      const customLimiter = createRateLimiter({ max: 2 });
      const testApp = express();
      testApp.use(customLimiter);
      testApp.get('/test', (_req, res) => res.json({ ok: true }));

      await request(testApp).get('/test');
      await request(testApp).get('/test');
      expect((await request(testApp).get('/test')).status).toBe(429);

      customLimiter.reset();

      // Immediately allowed after reset
      expect((await request(testApp).get('/test')).status).toBe(200);
    });
  });
});

