import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { TaskQueue } from '../src/queue/task-queue.js';
import { WorkerPool } from '../src/queue/worker-pool.js';
import { Task, Priority } from '../src/queue/types.js';

describe('Graceful Shutdown', () => {
  let queue: TaskQueue;
  let pool: WorkerPool;

  const createTask = (id: string, payload = {}): Task => ({
    id,
    payload,
    priority: Priority.NORMAL,
    status: 'pending',
    createdAt: new Date(),
    attempts: 0,
    maxAttempts: 3,
  });

  beforeEach(() => {
    queue = new TaskQueue();
  });

  afterEach(async () => {
    if (pool && !pool.isPoolStopped()) {
      await pool.stop(1000);
    }
  });

  describe('in-progress task completion on stop', () => {
    it('starts a slow task, calls stop(), and verifies the task completes before workers exit', async () => {
      let taskStarted = false;
      let taskFinished = false;
      let stopResolved = false;

      const slowTaskDurationMs = 120;

      const handler = async (_task: Task) => {
        taskStarted = true;
        await new Promise((resolve) => setTimeout(resolve, slowTaskDurationMs));
        taskFinished = true;
        return { success: true, data: { status: 'slow-work-done' } };
      };

      pool = new WorkerPool(queue, handler, { pollIntervalMs: 10 });
      pool.start(1);

      const slowTask = createTask('slow-task-1');
      queue.enqueue(slowTask);

      // 1. Wait until the worker has started processing the task
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (taskStarted) {
            clearInterval(check);
            resolve();
          }
        }, 5);
      });

      expect(taskStarted).toBe(true);
      expect(taskFinished).toBe(false);

      // 2. Call stop() while the task is still in progress
      const stopPromise = pool.stop(5000).then(() => {
        stopResolved = true;
      });

      // Immediately after calling stop():
      // The task is still running, so stopPromise must NOT have resolved yet
      expect(stopResolved).toBe(false);
      expect(taskFinished).toBe(false);

      // 3. Await graceful shutdown
      await stopPromise;

      // 4. Verify: Task completed BEFORE workers exited and stop resolved
      expect(taskFinished).toBe(true);
      expect(stopResolved).toBe(true);
      expect(slowTask.status).toBe('completed');
      expect(slowTask.completedAt).toBeInstanceOf(Date);
      expect(slowTask.result?.success).toBe(true);

      // Confirms all workers exited
      expect(pool.getWorkers()).toHaveLength(0);
      expect(pool.getStats().totalWorkers).toBe(0);
      expect(pool.getStats().activeWorkers).toBe(0);
      expect(pool.getStats().processedCount).toBe(1);
    });

    it('does not dequeue new tasks while awaiting in-progress tasks during shutdown', async () => {
      let activeTaskStarted = false;
      let secondTaskExecuted = false;

      const handler = async (task: Task) => {
        if (task.id === 'running-task') {
          activeTaskStarted = true;
          await new Promise((resolve) => setTimeout(resolve, 80));
          return { success: true };
        }
        if (task.id === 'queued-task') {
          secondTaskExecuted = true;
          return { success: true };
        }
        return { success: true };
      };

      pool = new WorkerPool(queue, handler, { pollIntervalMs: 10 });
      pool.start(1);

      const task1 = createTask('running-task');
      const task2 = createTask('queued-task');

      queue.enqueue(task1);

      // Wait until task1 starts
      await new Promise<void>((resolve) => {
        const check = setInterval(() => {
          if (activeTaskStarted) {
            clearInterval(check);
            resolve();
          }
        }, 5);
      });

      // Enqueue task2 while task1 is running
      queue.enqueue(task2);

      // Initiate shutdown
      await pool.stop(5000);

      // Task 1 finished
      expect(task1.status).toBe('completed');

      // Task 2 was never dequeued and remained pending
      expect(secondTaskExecuted).toBe(false);
      expect(task2.status).toBe('pending');
      expect(queue.size()).toBe(1);
      expect(queue.peek()?.id).toBe('queued-task');
    });
  });
});

