/**
 * Lifecycle states of a task in the queue system.
 */
export type TaskStatus =
  | 'pending'
  | 'running'
  | 'completed'
  | 'failed'
  | 'scheduled'
  | 'dead_letter';

/**
 * Numeric priority level. Higher values take precedence.
 */
export type TaskPriority = number;

/**
 * Standard priority constants for convenience.
 */
export const Priority = {
  LOW: 1,
  NORMAL: 5,
  HIGH: 10,
  CRITICAL: 20,
} as const;

/**
 * Result returned by a task handler upon execution.
 */
export interface TaskResult<T = unknown> {
  /** Indicates whether the task succeeded or failed */
  success: boolean;
  /** Optional response data on success */
  data?: T;
  /** Optional error message on failure */
  error?: string;
}

/**
 * Configuration options for the priority queue.
 */
export interface QueueConfig {
  maxConcurrency?: number;
  defaultMaxAttempts?: number;
  defaultPriority?: TaskPriority;
  pollIntervalMs?: number;
}

/**
 * Configuration options for worker polling and retry backoff.
 */
export interface WorkerConfig {
  /** Optional identifier for the worker */
  id?: string;
  /** Interval in milliseconds between queue polling attempts */
  pollIntervalMs?: number;
  /** Initial delay in milliseconds for exponential retry backoff */
  initialBackoffMs?: number;
  /** Multiplier applied to backoff delay on each subsequent retry attempt */
  backoffMultiplier?: number;
  /** Maximum backoff delay cap in milliseconds */
  maxBackoffMs?: number;
}

/**
 * Represents a discrete task entity managed by the queue system.
 */
export interface Task<T = unknown> {
  /** Unique task identifier */
  id: string;
  /** User-provided task payload */
  payload: T;
  /** Task priority (higher priority tasks are dequeued first) */
  priority: TaskPriority;
  /** Current lifecycle status */
  status: TaskStatus;
  /** Timestamp when the task was initially created */
  createdAt: Date;
  /** Timestamp when execution started */
  startedAt?: Date | null;
  /** Timestamp when execution finished */
  completedAt?: Date | null;
  /** Number of processing attempts executed */
  attempts: number;
  /** Maximum number of retry attempts permitted before moving to DLQ */
  maxAttempts: number;
  /** Execution output or error recorded by worker */
  result?: TaskResult | null;
  /** Optional future timestamp when the task becomes eligible for processing */
  scheduledAt?: Date | null;
  /** Optional list of task IDs that must complete before this task can be dequeued */
  dependsOn?: string[];
}

