import { Task, TaskStatus } from './types.js';

/**
 * Filter criteria for querying tasks from a TaskStore.
 */
export interface TaskStoreFilter {
  /** Optional status filter */
  status?: TaskStatus;
}

/**
 * Common storage interface for persisting and retrieving tasks.
 * Prepares the queue system for alternative database-backed persistence engines.
 */
export interface TaskStore {
  /**
   * Persists or updates a task in the store.
   * @param task - The task to save.
   */
  save(task: Task): Promise<void> | void;

  /**
   * Retrieves a task by its unique identifier.
   * @param id - The task ID.
   * @returns The matching task or undefined if not found.
   */
  get(id: string): Promise<Task | undefined> | Task | undefined;

  /**
   * Retrieves all tasks in the store, optionally filtered.
   * @param filter - Optional query filter.
   * @returns Array of matching tasks.
   */
  getAll(filter?: TaskStoreFilter): Promise<Task[]> | Task[];

  /**
   * Deletes a task from the store by its identifier.
   * @param id - The task ID.
   * @returns True if deleted, false if not found.
   */
  delete(id: string): Promise<boolean> | boolean;

  /**
   * Clears all tasks from the store.
   */
  clear(): Promise<void> | void;

  /**
   * Returns the count of tasks currently held in the store.
   */
  count(): Promise<number> | number;

  /**
   * Checks whether a task exists in the store.
   * @param id - The task ID.
   */
  has(id: string): Promise<boolean> | boolean;
}

/**
 * In-memory implementation of TaskStore using a JavaScript Map.
 */
export class InMemoryTaskStore implements TaskStore {
  private tasks: Map<string, Task> = new Map();

  /**
   * Saves a task in memory.
   * @param task - The task to store.
   */
  public save(task: Task): void {
    this.tasks.set(task.id, task);
  }

  /**
   * Retrieves a task by ID from memory.
   * @param id - The task ID.
   * @returns The task if found, otherwise undefined.
   */
  public get(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  /**
   * Returns all tasks in memory, optionally filtered by status.
   * @param filter - Optional filter options.
   * @returns Array of tasks.
   */
  public getAll(filter?: TaskStoreFilter): Task[] {
    const all = Array.from(this.tasks.values());
    if (filter?.status) {
      return all.filter((t) => t.status === filter.status);
    }
    return all;
  }

  /**
   * Deletes a task by ID from memory.
   * @param id - The task ID.
   * @returns True if deleted, false if not present.
   */
  public delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  /**
   * Removes all tasks from memory.
   */
  public clear(): void {
    this.tasks.clear();
  }

  /**
   * Returns the total count of stored tasks.
   */
  public count(): number {
    return this.tasks.size;
  }

  /**
   * Checks if a task ID exists in memory.
   * @param id - The task ID.
   */
  public has(id: string): boolean {
    return this.tasks.has(id);
  }
}

