import { Task, QueueConfig } from './types.js';
import { TaskStore, InMemoryTaskStore } from './task-store.js';

interface QueueItem {
  task: Task;
  seq: number;
}

export class TaskQueue {
  private items: QueueItem[] = [];
  private sequence = 0;
  private store: TaskStore;
  private completedTaskIds: Set<string> = new Set();
  private config: QueueConfig;

  constructor(
    config: QueueConfig = {},
    store: TaskStore = new InMemoryTaskStore()
  ) {
    this.config = config;
    this.store = store;
  }

  public getStore(): TaskStore {
    return this.store;
  }

  private compare(a: QueueItem, b: QueueItem): number {
    if (a.task.priority !== b.task.priority) {
      // Highest priority first (descending)
      return b.task.priority - a.task.priority;
    }
    // FIFO within the same priority (ascending sequence)
    return a.seq - b.seq;
  }

  public isTaskCompleted(taskId: string): boolean {
    if (this.completedTaskIds.has(taskId)) {
      return true;
    }
    const task = this.getTask(taskId);
    return task !== undefined && task.status === 'completed';
  }

  public markTaskCompleted(taskId: string): void {
    this.completedTaskIds.add(taskId);
    const task = this.getTask(taskId);
    if (task) {
      task.status = 'completed';
      void this.store.save(task);
    }
  }

  public areDependenciesSatisfied(task: Task): boolean {
    if (!task.dependsOn || task.dependsOn.length === 0) {
      return true;
    }
    return task.dependsOn.every((depId) => this.isTaskCompleted(depId));
  }

  public enqueue(task: Task): void {
    if (this.config.defaultPriority !== undefined && task.priority === undefined) {
      task.priority = this.config.defaultPriority;
    }
    if (this.config.defaultMaxAttempts !== undefined && task.maxAttempts === undefined) {
      task.maxAttempts = this.config.defaultMaxAttempts;
    }

    const item: QueueItem = { task, seq: this.sequence++ };

    // Binary search for insertion position to maintain priority order
    let low = 0;
    let high = this.items.length;
    while (low < high) {
      const mid = (low + high) >>> 1;
      if (this.compare(item, this.items[mid]) < 0) {
        high = mid;
      } else {
        low = mid + 1;
      }
    }
    this.items.splice(low, 0, item);
    void this.store.save(task);
  }

  public dequeue(): Task | null {
    for (let i = 0; i < this.items.length; i++) {
      const item = this.items[i];
      if (this.areDependenciesSatisfied(item.task)) {
        this.items.splice(i, 1);
        return item.task;
      }
    }
    return null;
  }

  public peek(): Task | null {
    for (let i = 0; i < this.items.length; i++) {
      const item = this.items[i];
      if (this.areDependenciesSatisfied(item.task)) {
        return item.task;
      }
    }
    return null;
  }

  public size(): number {
    return this.items.length;
  }

  public isEmpty(): boolean {
    return this.items.length === 0;
  }

  public clear(): void {
    this.items = [];
    this.sequence = 0;
    void this.store.clear();
    this.completedTaskIds.clear();
  }

  public getTask(id: string): Task | undefined {
    return this.store.get(id) as Task | undefined;
  }

  public getAllTasks(): Task[] {
    return this.store.getAll() as Task[];
  }

  public getConfig(): QueueConfig {
    return { ...this.config };
  }
}

