   */
  public peek(): Task | null {
    for (let i = 0; i < this.items.length; i++) {
      const item = this.items[i];
      if (this.areDependenciesSatisfied(item.task)) {
        return item.task;
      }
    }
    return null;
  }

  /**
   * Returns the count of items currently waiting in the queue.
   */
  public size(): number {
    return this.items.length;
  }

  /**
   * Indicates whether the queue contains no items.
   */
  public isEmpty(): boolean {
    return this.items.length === 0;
  }

  /**
   * Removes all items from the queue and clears tracked store tasks.
   */
  public clear(): void {
    this.items = [];
    this.sequence = 0;
    void this.store.clear();
    this.completedTaskIds.clear();
  }

