   * Retrieves a task by ID from the queue's backing store.
   * @param id - The task ID to look up.
   */
  public getTask(id: string): Task | undefined {
    return this.store.get(id) as Task | undefined;
  }

  /**
   * Returns all tasks recorded in the backing store.
   */
  public getAllTasks(): Task[] {
    return this.store.getAll() as Task[];
  }

  /**
   * Returns a copy of the queue configuration.
   */
  public getConfig(): QueueConfig {
    return { ...this.config };
  }
}

