   */
  constructor(
    queue: TaskQueue,
    handler: TaskHandler,
    config: WorkerConfig = {},
    dlq?: DeadLetterQueue
  ) {
    this.queue = queue;
    this.handler = handler;
    this.config = config;
    this.dlq = dlq;
    this.id = config.id ?? `worker-${randomUUID()}`;
  }

