   * Returns the attached MetricsCollector, if any.
   */
  public getMetrics(): MetricsCollector | undefined {
    return this.metrics;
  }

  /**
   * Returns true if the worker's polling loop is active.
   */
  public isRunning(): boolean {
    return this.running;
  }

  /**
   * Returns true if the worker is currently processing a task.
   */
  public isBusy(): boolean {
    return this.currentTask !== null;
  }

  /**
   * Returns the task currently being processed, or null if idle.
   */
  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

