import { Task } from './types.js';
import { TaskQueue } from './task-queue.js';

/**
 * Record representing a failed task quarantined in the Dead Letter Queue.
 */
export interface DeadLetterEntry {
  /** The failed task */
  task: Task;
  /** Timestamp when the task was relegated to the DLQ */
  failedAt: Date;
  /** Error message or reason for terminal failure */
  lastError: string;
}

/**
 * Manages tasks that have permanently failed after exceeding maxAttempts.
 * Enables auditing, manual replay/retry into the main queue, and purging.
 */
export class DeadLetterQueue {
  private queue?: TaskQueue;
  private entries: Map<string, DeadLetterEntry> = new Map();

  /**
   * Initializes the DeadLetterQueue.
   * @param queue - Optional primary TaskQueue to re-enqueue retried tasks into.
   */
  constructor(queue?: TaskQueue) {
    this.queue = queue;
  }

  /**
   * Links or updates the primary TaskQueue reference.
   * @param queue - Primary TaskQueue instance.
   */
  public setQueue(queue: TaskQueue): void {
    this.queue = queue;
  }

  /**
   * Quarantines a task in the dead-letter queue.
   * @param task - The failed task.
   * @param lastError - Optional error description.
   */
  public add(task: Task, lastError?: string): void {
    const errorMsg =
      lastError ??
      task.result?.error ??
      'Task exceeded maximum retry attempts';

    task.status = 'dead_letter';
    this.entries.set(task.id, {
      task,
      failedAt: new Date(),
      lastError: errorMsg,
    });
  }

  /**
   * Lists all quarantined entries in the dead-letter queue.
   * @returns Array of DeadLetterEntry records.
   */
  public list(): DeadLetterEntry[] {
    return Array.from(this.entries.values());
  }

  /**
   * Retrieves a dead-letter entry by task ID.
   * @param taskId - The task ID to look up.
   * @returns The DeadLetterEntry if present, otherwise undefined.
   */
  public get(taskId: string): DeadLetterEntry | undefined {
    return this.entries.get(taskId);
  }

  /**
   * Removes a task from the DLQ and re-enqueues it into the main priority queue.
   * @param taskId - The ID of the task to retry.
   * @param targetQueue - Optional queue to enqueue into (defaults to configured queue).
   * @returns The retried task if found, or null if not in the DLQ.
   */
  public retry(taskId: string, targetQueue?: TaskQueue): Task | null {
    const entry = this.entries.get(taskId);
    if (!entry) {
      return null;
    }

    this.entries.delete(taskId);
    const task = entry.task;
    task.status = 'pending';
    task.attempts = 0;
    task.result = null;

    const queue = targetQueue ?? this.queue;
    if (queue) {
      queue.enqueue(task);
    }

    return task;
  }

  /**
   * Removes all entries from the dead-letter queue.
   * @returns The count of purged tasks.
   */
  public purge(): number {
    const count = this.entries.size;
    this.entries.clear();
    return count;
  }

  /**
   * Returns the count of tasks currently in the DLQ.
   */
  public size(): number {
    return this.entries.size;
  }
}

