import { Task } from './types.js';
import { TaskQueue } from './task-queue.js';
import { TaskStore, InMemoryTaskStore } from './task-store.js';

export interface SchedulerConfig {
  checkIntervalMs?: number;
}

export class Scheduler {
  private queue: TaskQueue;
  private config: SchedulerConfig;
  private store: TaskStore;
  private timer: NodeJS.Timeout | null = null;
  private running = false;

  constructor(
    queue: TaskQueue,
    config: SchedulerConfig = {},
    store: TaskStore = new InMemoryTaskStore()
  ) {
    this.queue = queue;
    this.config = config;
    this.store = store;
  }

  public getStore(): TaskStore {
    return this.store;
  }

  public schedule(task: Task): void {
    task.status = 'scheduled';
    void this.store.save(task);
  }

  public getScheduledTasks(): Task[] {
    return this.store.getAll() as Task[];
  }

  public getTask(id: string): Task | undefined {
    return this.store.get(id) as Task | undefined;
  }

  public cancel(id: string): boolean {
    return this.store.delete(id) as boolean;
  }

  public checkDueTasks(now: Date = new Date()): Task[] {
    const dueTasks: Task[] = [];
    const currentTime = now.getTime();
    const tasks = this.store.getAll() as Task[];

    for (const task of tasks) {
      const scheduledTime = task.scheduledAt
        ? new Date(task.scheduledAt).getTime()
        : 0;

      if (scheduledTime <= currentTime) {
        void this.store.delete(task.id);
        task.status = 'pending';
        this.queue.enqueue(task);
        dueTasks.push(task);
      }
    }

    return dueTasks;
  }

  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    const interval = this.config.checkIntervalMs ?? 1000;
    this.timer = setInterval(() => {
      this.checkDueTasks();
    }, interval);
  }

  public stop(): void {
    this.running = false;
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  public isRunning(): boolean {
    return this.running;
  }

  public size(): number {
    return this.store.count() as number;
  }

  public clear(): void {
    void this.store.clear();
  }
}

