import { Task } from './types.js';
import { TaskQueue } from './task-queue.js';
import { TaskStore, InMemoryTaskStore } from './task-store.js';

/**
 * Configuration options for the task Scheduler.
 */
export interface SchedulerConfig {
  /** Periodic polling interval in milliseconds (default: 1000ms / 1 second) */
  checkIntervalMs?: number;
}

/**
 * Holds tasks with future scheduled timestamps and moves them to the
 * main priority queue when their due time arrives.
 */
export class Scheduler {
  private queue: TaskQueue;
  private config: SchedulerConfig;
  private store: TaskStore;
  private timer: NodeJS.Timeout | null = null;
  private running = false;

  /**
   * Initializes the Scheduler.
   * @param queue - Target priority queue to deliver due tasks to.
   * @param config - Optional scheduler configuration.
   * @param store - Backing storage engine for holding scheduled tasks.
   */
  constructor(
    queue: TaskQueue,
    config: SchedulerConfig = {},
    store: TaskStore = new InMemoryTaskStore()
  ) {
    this.queue = queue;
    this.config = config;
    this.store = store;
  }

  /**
   * Returns the underlying TaskStore for scheduled tasks.
   */
  public getStore(): TaskStore {
    return this.store;
  }

  /**
   * Registers a future task to be held by the scheduler.
   * @param task - The task with scheduledAt set in the future.
   */
  public schedule(task: Task): void {
    task.status = 'scheduled';
    void this.store.save(task);
  }

  /**
   * Returns all tasks currently held awaiting their due timestamp.
   */
  public getScheduledTasks(): Task[] {
    return this.store.getAll() as Task[];
  }

  /**
   * Retrieves a scheduled task by ID.
   * @param id - Task ID to look up.
   */
  public getTask(id: string): Task | undefined {
    return this.store.get(id) as Task | undefined;
  }

  /**
   * Cancels a scheduled task before it is dispatched to the main queue.
   * @param id - ID of the task to cancel.
   * @returns True if found and removed; false otherwise.
   */
  public cancel(id: string): boolean {
    return this.store.delete(id) as boolean;
  }

  /**
   * Checks for all tasks whose scheduled timestamp has arrived and moves them
   * to the main queue with status 'pending'.
   * @param now - Reference timestamp to compare against (defaults to new Date()).
   * @returns Array of tasks dispatched to the queue.
   */
  public checkDueTasks(now: Date = new Date()): Task[] {
    const dueTasks: Task[] = [];
    const currentTime = now.getTime();
    const tasks = this.store.getAll() as Task[];

    for (const task of tasks) {
      const scheduledTime = task.scheduledAt
        ? new Date(task.scheduledAt).getTime()
        : 0;

      if (scheduledTime <= currentTime) {
        void this.store.delete(task.id);
        task.status = 'pending';
        this.queue.enqueue(task);
        dueTasks.push(task);
      }
    }

    return dueTasks;
  }

  /**
   * Starts the periodic evaluation timer (every second by default).
   */
  public start(): void {
    if (this.running) {
      return;
    }
    this.running = true;
    const interval = this.config.checkIntervalMs ?? 1000;
    this.timer = setInterval(() => {
      this.checkDueTasks();
    }, interval);
  }

  /**
   * Stops the evaluation timer.
   */
  public stop(): void {
    this.running = false;
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }

  /**
   * Indicates whether the scheduler polling timer is actively running.
   */
  public isRunning(): boolean {
    return this.running;
  }

  /**
   * Returns the count of scheduled tasks currently held.
   */
  public size(): number {
    return this.store.count() as number;
  }

  /**
   * Removes all held scheduled tasks.
   */
  public clear(): void {
    void this.store.clear();
  }
}

