import { TaskQueue } from './task-queue.js';

/**
 * A time-series sample representing priority queue depth at a specific epoch timestamp.
 */
export interface QueueDepthSample {
  /** Milliseconds epoch timestamp */
  timestamp: number;
  /** Number of pending tasks in the queue at this timestamp */
  depth: number;
}

/**
 * Aggregated telemetry metrics for the task queue system.
 */
export interface MetricsData {
  /** Total number of tasks successfully processed */
  tasksProcessed: number;
  /** Total number of tasks that failed execution */
  tasksFailed: number;
  /** Mean execution duration in milliseconds across completed tasks */
  avgProcessingTimeMs: number;
  /** Periodic queue depth historical snapshots */
  queueDepthOverTime: QueueDepthSample[];
}

/**
 * Collects runtime performance metrics and samples periodic queue depth telemetry.
 */
export class MetricsCollector {
  private queue: TaskQueue;
  private tasksProcessed = 0;
  private tasksFailed = 0;
  private totalProcessingTimeMs = 0;
  private queueDepthOverTime: QueueDepthSample[] = [];
  private sampleTimer: NodeJS.Timeout | null = null;
  private maxSamples: number;

  /**
   * Initializes the MetricsCollector.
   * @param queue - TaskQueue to observe.
   * @param options - Optional configuration (e.g. maxSamples retention cap).
   */
  constructor(queue: TaskQueue, options: { maxSamples?: number } = {}) {
    this.queue = queue;
    this.maxSamples = options.maxSamples ?? 3600;
  }

  /**
   * Records execution duration for a successfully completed task.
   * @param durationMs - Execution time in milliseconds.
   */
  public recordTaskCompleted(durationMs: number): void {
    this.tasksProcessed++;
    this.totalProcessingTimeMs += durationMs;
  }

  /**
   * Records execution of a failed task.
   * @param durationMs - Execution time in milliseconds (default 0).
   */
  public recordTaskFailed(durationMs = 0): void {
    this.tasksFailed++;
    this.totalProcessingTimeMs += durationMs;
  }

  /**
   * Captures a snapshot of current queue depth.
   * @param depth - Optional explicit depth override.
   */
  public sampleQueueDepth(depth?: number): void {
    const currentDepth = depth !== undefined ? depth : this.queue.size();
    this.queueDepthOverTime.push({
      timestamp: Date.now(),
      depth: currentDepth,
    });
    if (this.queueDepthOverTime.length > this.maxSamples) {
      this.queueDepthOverTime.shift();
    }
  }

  /**
   * Starts periodic queue depth sampling (every second by default).
   * @param intervalMs - Sampling interval in milliseconds.
   */
  public start(intervalMs = 1000): void {
    if (this.sampleTimer) {
      return;
    }
    this.sampleQueueDepth();
    this.sampleTimer = setInterval(() => {
      this.sampleQueueDepth();
    }, intervalMs);

    if (typeof this.sampleTimer.unref === 'function') {
      this.sampleTimer.unref();
    }
  }

  /**
   * Stops the sampling timer.
   */
  public stop(): void {
    if (this.sampleTimer) {
      clearInterval(this.sampleTimer);
      this.sampleTimer = null;
    }
  }

  /**
   * Returns current aggregate metrics snapshot.
   */
  public getMetrics(): MetricsData {
    const avg =
      this.tasksProcessed > 0
        ? Math.round((this.totalProcessingTimeMs / this.tasksProcessed) * 100) / 100
        : 0;

    return {
      tasksProcessed: this.tasksProcessed,
      tasksFailed: this.tasksFailed,
      avgProcessingTimeMs: avg,
      queueDepthOverTime: [...this.queueDepthOverTime],
    };
  }

  /**
   * Resets all metric counters and sampled time-series data.
   */
  public reset(): void {
    this.tasksProcessed = 0;
    this.tasksFailed = 0;
    this.totalProcessingTimeMs = 0;
    this.queueDepthOverTime = [];
  }
}

