import { Router, Request, Response } from 'express';
import { randomUUID } from 'node:crypto';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';
import { Scheduler } from '../queue/scheduler.js';
import { MetricsCollector } from '../queue/metrics.js';

export const defaultQueue = new TaskQueue();
export const defaultDlq = new DeadLetterQueue(defaultQueue);
export const defaultPool = new WorkerPool(
  defaultQueue,
  async (task: Task) => ({ success: true, data: task.payload }),
  { pollIntervalMs: 20 },
  defaultDlq
);
export const defaultScheduler = new Scheduler(defaultQueue, { checkIntervalMs: 1000 });
export const defaultMetrics = new MetricsCollector(defaultQueue);
defaultPool.setMetrics(defaultMetrics);
defaultMetrics.start(1000);

export interface QueueRouterOptions {
  queue?: TaskQueue;
  dlq?: DeadLetterQueue;
  pool?: WorkerPool;
  scheduler?: Scheduler;
  metrics?: MetricsCollector;
}

/**
 * Creates and configures an Express router for queue REST API operations.
 *
 * @param options - Configuration options and dependency overrides.
 * @returns Configured Express Router.
 */
export function createQueueRouter(options: QueueRouterOptions = {}): Router {
  const router = Router();
  const queue = options.queue ?? defaultQueue;
  const dlq = options.dlq ?? defaultDlq;
  const pool = options.pool ?? defaultPool;
  const scheduler = options.scheduler ?? defaultScheduler;
  const metrics = options.metrics ?? defaultMetrics;

  /**
   * Handles POST /api/v1/tasks — Enqueues a new task with optional priority, scheduling, and dependencies.
   *
   * @param req - Express request containing the task body.
   * @param res - Express response returning 201 with the created task.
   */
  const enqueueTaskHandler = (req: Request, res: Response): void => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const id = typeof body.id === 'string' && body.id.trim().length > 0 ? body.id : randomUUID();
      const priority = typeof body.priority === 'number' ? body.priority : 5;
      const maxAttempts = typeof body.maxAttempts === 'number' && body.maxAttempts > 0 ? body.maxAttempts : 3;
      const payload = body.payload !== undefined ? body.payload : body;

      let scheduledAt: Date | undefined;
      if (body.scheduledAt !== undefined && body.scheduledAt !== null) {
        scheduledAt = new Date(body.scheduledAt as string | number | Date);
        if (Number.isNaN(scheduledAt.getTime())) {
          res.status(400).json({ error: 'Invalid scheduledAt timestamp' });
          return;
        }
      }

      const isFuture = scheduledAt !== undefined && scheduledAt.getTime() > Date.now();

      const task: Task = {
        id,
        payload,
        priority,
        status: isFuture ? 'scheduled' : 'pending',
        createdAt: new Date(),
        attempts: 0,
        maxAttempts,
        ...(scheduledAt ? { scheduledAt } : {}),
        ...(Array.isArray(body.dependsOn) ? { dependsOn: body.dependsOn as string[] } : {}),
      };

      if (isFuture) {
        if (scheduler) {
          scheduler.schedule(task);
        } else {
          const delay = scheduledAt!.getTime() - Date.now();
          setTimeout(() => {
            task.status = 'pending';
            queue.enqueue(task);
          }, delay);
        }
      } else {
        queue.enqueue(task);
      }

      res.status(201).json(task);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };

  /**
   * Handles GET /api/v1/metrics — Retrieves aggregated performance and queue depth metrics.
   *
   * @param _req - Express request object.
   * @param res - Express response object returning MetricsData.
   */
  const getMetricsHandler = (_req: Request, res: Response): void => {
    res.status(200).json(metrics.getMetrics());
  };

  /**
   * Handles GET /api/v1/queue/stats — Retrieves real-time queue depth and worker pool telemetry.
   *
   * @param _req - Express request object.
   * @param res - Express response object returning queue and pool statistics.
   */
  const getQueueStatsHandler = (_req: Request, res: Response): void => {
    const poolStats = pool ? pool.getStats() : undefined;
    const stats = {
      queueDepth: queue.size(),
      activeWorkers: poolStats?.activeWorkers ?? 0,
      totalWorkers: poolStats?.totalWorkers ?? 0,
      idleWorkers: poolStats?.idleWorkers ?? 0,
      processedCount: poolStats?.processedCount ?? 0,
      failedCount: poolStats?.failedCount ?? 0,
      dlqCount: dlq ? dlq.size() : 0,
      scheduledCount: scheduler ? scheduler.size() : 0,
    };
    res.status(200).json(stats);
  };

  /**
   * Handles POST /api/v1/workers/scale — Dynamically adjusts the number of workers in the pool.
   *
   * @param req - Express request containing target count/workers.
   * @param res - Express response confirming the scale operation and updated stats.
   */
  const scaleWorkersHandler = async (req: Request, res: Response): Promise<void> => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const rawCount = body.count ?? body.workers ?? body.n ?? body.scale;
      const count =
        typeof rawCount === 'number'
          ? rawCount
          : typeof rawCount === 'string'
          ? parseInt(rawCount, 10)
          : undefined;

      if (count === undefined || Number.isNaN(count) || count < 0) {
        res.status(400).json({ error: 'Worker count must be a non-negative number' });
        return;
      }

      if (pool) {
        await pool.scale(count);
        const stats = pool.getStats();
        res.status(200).json({
          message: `Scaled workers to ${count}`,
          count,
          totalWorkers: count,
          stats,
        });
        return;
      }

      res.status(200).json({
        message: `Scaled workers to ${count}`,
        count,
        totalWorkers: count,
      });
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };

  /**
   * Handles GET /api/v1/dlq — Lists all dead-lettered task records.
   *
   * @param _req - Express request object.
   * @param res - Express response returning array of DeadLetterEntry items.
   */
  const listDlqHandler = (_req: Request, res: Response): void => {
    const entries = dlq ? dlq.list() : [];
    res.status(200).json(entries);
  };

  /**
   * Handles POST /api/v1/dlq/:id/retry — Retries a task from the DLQ by returning it to the main queue.
   *
   * @param req - Express request containing the dead-lettered task ID in params.
   * @param res - Express response returning 200 with the retried task, or 404 if not found.
   */
  const retryDlqTaskHandler = (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';

    if (!id) {
      res.status(400).json({ error: 'Task ID is required' });
      return;
    }

    const task = dlq ? dlq.retry(id, queue) : null;
    if (!task) {
      res.status(404).json({ error: 'Task not found in dead-letter queue', id });
      return;
    }

    res.status(200).json({
      message: `Task ${id} retried successfully`,
      task,
      ...task,
    });
  };

  /**
   * Handles GET /api/v1/tasks/:id — Retrieves the status and details of a single task by ID.
   *
   * @param req - Express request containing the task ID in params.
   * @param res - Express response returning 200 with the task or 404 if not found.
   */
  const getTaskByIdHandler = (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const task = queue.getTask(id) ?? dlq?.get(id)?.task ?? scheduler?.getTask(id);

    if (!task) {
      res.status(404).json({ error: 'Task not found', id });
      return;
    }

    res.status(200).json(task);
  };

  /**
   * Handles GET /api/v1/tasks — Lists tasks across queue and DLQ with optional status filtering.
   *
   * @param req - Express request with optional `status` query parameter.
   * @param res - Express response returning array of matching tasks.
   */
  const listTasksHandler = (req: Request, res: Response): void => {
    const { status } = req.query;
    let tasks = queue.getAllTasks();
    const existingIds = new Set(tasks.map((t) => t.id));

    if (dlq) {
      const dlqTasks = dlq.list().map((e) => e.task);
      for (const dt of dlqTasks) {
        if (!existingIds.has(dt.id)) {
          tasks.push(dt);
          existingIds.add(dt.id);
        }
      }
    }

    if (scheduler) {
      const scheduledTasks = scheduler.getScheduledTasks();
      for (const st of scheduledTasks) {
        if (!existingIds.has(st.id)) {
          tasks.push(st);
          existingIds.add(st.id);
        }
      }
    }

    if (typeof status === 'string' && status.trim().length > 0) {
      tasks = tasks.filter((t) => t.status === status);
    }

    res.status(200).json(tasks);
  };

  router.post(['/tasks', '/api/v1/tasks'], enqueueTaskHandler);
  router.get(['/metrics', '/api/v1/metrics'], getMetricsHandler);
  router.get(['/queue/stats', '/api/v1/queue/stats'], getQueueStatsHandler);
  router.post(['/workers/scale', '/api/v1/workers/scale'], scaleWorkersHandler);
  router.get(['/dlq', '/api/v1/dlq'], listDlqHandler);
  router.post(['/dlq/:id/retry', '/api/v1/dlq/:id/retry'], retryDlqTaskHandler);
  router.get(['/tasks/:id', '/api/v1/tasks/:id'], getTaskByIdHandler);
  router.get(['/tasks', '/api/v1/tasks'], listTasksHandler);

  return router;
}

export const queueRouter = createQueueRouter();
export default queueRouter;

