import { Request, Response, NextFunction } from 'express';

export interface RateLimiterOptions {
  windowMs?: number;
  max?: number;
  message?: string;
}

export interface RateLimiterMiddleware {
  (req: Request, res: Response, next: NextFunction): void;
  reset(): void;
  getHits(ip: string): number;
}

export function createRateLimiter(options: RateLimiterOptions = {}): RateLimiterMiddleware {
  const windowMs = options.windowMs ?? 60 * 1000; // 1 minute default
  const max = options.max ?? 100; // 100 requests per minute default
  const message =
    options.message ??
    `Rate limit exceeded. Max ${max} requests per minute.`;

  const ipRequests = new Map<string, number[]>();

  const middleware = (req: Request, res: Response, next: NextFunction): void => {
    const forwarded = req.headers['x-forwarded-for'];
    const rawIp =
      (typeof forwarded === 'string' && forwarded) ||
      (Array.isArray(forwarded) && forwarded[0]) ||
      req.ip ||
      req.socket?.remoteAddress ||
      '127.0.0.1';

    const ip =
      typeof rawIp === 'string'
        ? rawIp.split(',')[0].trim()
        : '127.0.0.1';

    const now = Date.now();
    const windowStart = now - windowMs;

    let timestamps = ipRequests.get(ip) ?? [];
    // Filter out timestamps outside the sliding window
    timestamps = timestamps.filter((t) => t > windowStart);

    if (timestamps.length >= max) {
      const oldestTimestamp = timestamps[0];
      const resetTime = oldestTimestamp + windowMs;
      const retryAfterSeconds = Math.max(1, Math.ceil((resetTime - now) / 1000));

      res.setHeader('Retry-After', String(retryAfterSeconds));
      res.setHeader('X-RateLimit-Limit', String(max));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetTime / 1000)));

      res.status(429).json({
        error: 'Too Many Requests',
        message,
        retryAfter: retryAfterSeconds,
      });
      return;
    }

    timestamps.push(now);
    ipRequests.set(ip, timestamps);

    res.setHeader('X-RateLimit-Limit', String(max));
    res.setHeader('X-RateLimit-Remaining', String(max - timestamps.length));

    next();
  };

  middleware.reset = (): void => {
    ipRequests.clear();
  };

  middleware.getHits = (ip: string): number => {
    const now = Date.now();
    const timestamps = ipRequests.get(ip) ?? [];
    return timestamps.filter((t) => t > now - windowMs).length;
  };

  return middleware;
}

export const rateLimiter = createRateLimiter();
export default rateLimiter;

