import { Request, Response, NextFunction } from 'express';

/**
 * Configuration options for sliding window rate limiting.
 */
export interface RateLimiterOptions {
  /** Time window in milliseconds (default: 60,000ms / 1 minute) */
  windowMs?: number;
  /** Maximum number of allowed requests per client IP within the window (default: 100) */
  max?: number;
  /** Custom error message when limit is exceeded */
  message?: string;
}

/**
 * Rate limiter Express middleware enhanced with state management utilities.
 */
export interface RateLimiterMiddleware {
  (req: Request, res: Response, next: NextFunction): void;
  /** Clears all tracked IP request history */
  reset(): void;
  /** Returns the current active hit count for a given IP address */
  getHits(ip: string): number;
}

/**
 * Creates an Express rate-limiting middleware using a sliding log window.
 *
 * @param options - Configuration options for window duration and request limits.
 * @returns RateLimiterMiddleware instance with reset and inspection capabilities.
 */
export function createRateLimiter(options: RateLimiterOptions = {}): RateLimiterMiddleware {
  const windowMs = options.windowMs ?? 60 * 1000; // 1 minute default
  const max = options.max ?? 100; // 100 requests per minute default
  const message =
    options.message ??
    `Rate limit exceeded. Max ${max} requests per minute.`;

  const ipRequests = new Map<string, number[]>();

  const middleware = (req: Request, res: Response, next: NextFunction): void => {
    const forwarded = req.headers['x-forwarded-for'];
    const rawIp =
      (typeof forwarded === 'string' && forwarded) ||
      (Array.isArray(forwarded) && forwarded[0]) ||
      req.ip ||
      req.socket?.remoteAddress ||
      '127.0.0.1';

    const ip =
      typeof rawIp === 'string'
        ? rawIp.split(',')[0].trim()
        : '127.0.0.1';

    const now = Date.now();
    const windowStart = now - windowMs;

    let timestamps = ipRequests.get(ip) ?? [];
    // Filter out timestamps outside the sliding window
    timestamps = timestamps.filter((t) => t > windowStart);

    if (timestamps.length >= max) {
      const oldestTimestamp = timestamps[0];
      const resetTime = oldestTimestamp + windowMs;
      const retryAfterSeconds = Math.max(1, Math.ceil((resetTime - now) / 1000));

      res.setHeader('Retry-After', String(retryAfterSeconds));
      res.setHeader('X-RateLimit-Limit', String(max));
      res.setHeader('X-RateLimit-Remaining', '0');
      res.setHeader('X-RateLimit-Reset', String(Math.ceil(resetTime / 1000)));

      res.status(429).json({
        error: 'Too Many Requests',
        message,
        retryAfter: retryAfterSeconds,
      });
      return;
    }

    timestamps.push(now);
    ipRequests.set(ip, timestamps);

    res.setHeader('X-RateLimit-Limit', String(max));
    res.setHeader('X-RateLimit-Remaining', String(max - timestamps.length));

    next();
  };

  middleware.reset = (): void => {
    ipRequests.clear();
  };

  middleware.getHits = (ip: string): number => {
    const now = Date.now();
    const timestamps = ipRequests.get(ip) ?? [];
    return timestamps.filter((t) => t > now - windowMs).length;
  };

  return middleware;
}

export const rateLimiter = createRateLimiter();
export default rateLimiter;

import { WorkerConfig, Task } from './types.js';
import { TaskQueue } from './task-queue.js';

/**
 * Calculates exponential backoff delay based on attempts count.
 *
 * @param attempts - Number of attempts made.
 * @param config - WorkerConfig containing backoff settings.
 * @returns Delay in milliseconds.
 */
export function calculateBackoff(attempts: number, config: WorkerConfig): number {
  const initial = config.initialBackoffMs ?? 100;
  const multiplier = config.backoffMultiplier ?? 2;
  const max = config.maxBackoffMs ?? 10000;
  const delay = initial * Math.pow(multiplier, Math.max(0, attempts - 1));
  return Math.min(delay, max);
}

/**
 * Schedules a failed task for re-enqueueing after an exponential backoff delay.
 *
 * @param task - The task to retry.
 * @param queue - The destination TaskQueue.
 * @param config - Worker configuration containing backoff settings.
 * @param onScheduled - Callback receiving the active timer and delay.
 * @returns The calculated delay in milliseconds.
 */
export function scheduleTaskRetry(
  task: Task,
  queue: TaskQueue,
  config: WorkerConfig,
  onScheduled: (timer: NodeJS.Timeout) => void
): number {
  const delay = calculateBackoff(task.attempts, config);
  const timer = setTimeout(() => {
    task.status = 'pending';
    queue.enqueue(task);
  }, delay);
  onScheduled(timer);
  return delay;
}

import { randomUUID } from 'node:crypto';
import { Task, TaskResult, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';
import { DeadLetterQueue } from './dead-letter-queue.js';
import { MetricsCollector } from './metrics.js';
import { calculateBackoff, scheduleTaskRetry } from './backoff.js';

export type TaskHandler = (task: Task) => Promise<TaskResult>;

/**
 * Worker responsible for polling the priority queue, executing tasks,
 * handling retries with exponential backoff, and reporting to DLQ and metrics.
 */
export class Worker {
  public readonly id: string;
  private queue: TaskQueue;
  private handler: TaskHandler;
  private config: WorkerConfig;
  private dlq?: DeadLetterQueue;
  private metrics?: MetricsCollector;
  private running = false;
  private currentTask: Task | null = null;
  private currentProcessingPromise: Promise<TaskResult> | null = null;
  private pollTimer: NodeJS.Timeout | null = null;
  private sleepResolve: (() => void) | null = null;
  private retryTimers: Set<NodeJS.Timeout> = new Set();

  constructor(
    queue: TaskQueue,
    handler: TaskHandler,
    config: WorkerConfig = {},
    dlq?: DeadLetterQueue
  ) {
    this.queue = queue;
    this.handler = handler;
    this.config = config;
    this.dlq = dlq;
    this.id = config.id ?? `worker-${randomUUID()}`;
  }

  public setDeadLetterQueue(dlq: DeadLetterQueue): void {
    this.dlq = dlq;
  }

  public getDeadLetterQueue(): DeadLetterQueue | undefined {
    return this.dlq;
  }

  public setMetrics(metrics: MetricsCollector): void {
    this.metrics = metrics;
  }

  public getMetrics(): MetricsCollector | undefined {
    return this.metrics;
  }

  public isRunning(): boolean {
    return this.running;
  }

  public isBusy(): boolean {
    return this.currentTask !== null;
  }

  public getCurrentTask(): Task | null {
    return this.currentTask;
  }

  public getConfig(): WorkerConfig {
    return { ...this.config };
  }

  public getPendingRetryCount(): number {
    return this.retryTimers.size;
  }

  public calculateBackoff(attempts: number): number {
    return calculateBackoff(attempts, this.config);
  }

  public scheduleRetry(task: Task): number {
    return scheduleTaskRetry(task, this.queue, this.config, (timer) => {
      this.retryTimers.add(timer);
    });
  }

  public start(): void {
    if (this.running) return;
    this.running = true;
    void this.poll();
  }

  public async stop(): Promise<void> {
    this.running = false;
    if (this.pollTimer) {
      clearTimeout(this.pollTimer);
      this.pollTimer = null;
    }
    if (this.sleepResolve) {
      const resolve = this.sleepResolve;
      this.sleepResolve = null;
      resolve();
    }
    for (const timer of this.retryTimers) {
      clearTimeout(timer);
    }
    this.retryTimers.clear();

    if (this.currentProcessingPromise) {
      try {
        await this.currentProcessingPromise;
      } catch {
        // Suppress unhandled rejections during worker shutdown
      }
    }
  }

  public async processNext(): Promise<Task | null> {
    if (this.currentTask) return null;
    const task = this.queue.dequeue();
    if (!task) return null;
    await this.processTask(task);
    return task;
  }

  public async processTask(task: Task): Promise<TaskResult> {
    this.currentTask = task;
    task.status = 'running';
    task.startedAt = new Date();
    task.attempts = (task.attempts || 0) + 1;
    if (task.maxAttempts === undefined || task.maxAttempts === null) {
      task.maxAttempts = this.queue.getConfig().defaultMaxAttempts ?? 3;
    }

    const executionPromise = (async (): Promise<TaskResult> => {
      let result: TaskResult;
      try {
        result = await this.handler(task);
      } catch (err) {
        result = {
          success: false,
          error: err instanceof Error ? err.message : String(err),
        };
      }

      task.result = result;
      task.completedAt = new Date();
      const startTime = task.startedAt ? task.startedAt.getTime() : Date.now();
      const duration = Math.max(0, task.completedAt.getTime() - startTime);

      if (result.success) {
        task.status = 'completed';
        this.metrics?.recordTaskCompleted(duration);
      } else {
        task.status = 'failed';
        this.metrics?.recordTaskFailed(duration);
        if (task.attempts < task.maxAttempts) {
          this.scheduleRetry(task);
        } else if (this.dlq) {
          this.dlq.add(task, result.error);
        }
      }

      return result;
    })();

    this.currentProcessingPromise = executionPromise;
    try {
      return await executionPromise;
    } finally {
      this.currentTask = null;
      this.currentProcessingPromise = null;
    }
  }

  private async poll(): Promise<void> {
    const pollInterval = this.config.pollIntervalMs ?? 50;
    while (this.running) {
      try {
        const task = await this.processNext();
        if (!task && this.running) {
          await this.sleep(pollInterval);
        }
      } catch {
        if (this.running) {
          await this.sleep(pollInterval);
        }
      }
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise<void>((resolve) => {
      this.sleepResolve = resolve;
      this.pollTimer = setTimeout(() => {
        this.pollTimer = null;
        this.sleepResolve = null;
        resolve();
      }, ms);
    });
  }
}

