/**
 * Real-time operational metrics for the worker pool.
 */
export interface WorkerPoolStats {
  /** Total number of workers registered in the pool */
  totalWorkers: number;
  /** Number of workers actively processing a task */
  activeWorkers: number;
  /** Number of workers running but currently idle */
  idleWorkers: number;
  /** Total tasks successfully processed by workers in this pool */
  processedCount: number;
  /** Total tasks that failed execution in this pool */
  failedCount: number;
}

import { Task, WorkerConfig } from './types.js';
import { TaskQueue } from './task-queue.js';
import { Worker, TaskHandler } from './worker.js';
import { DeadLetterQueue } from './dead-letter-queue.js';
import { MetricsCollector } from './metrics.js';
import { WorkerPoolStats } from './worker-pool-types.js';

export type { WorkerPoolStats };

/**
 * Manages a dynamic collection of Worker instances, providing scaling,
 * graceful shutdown, and aggregate execution statistics.
 */
export class WorkerPool {
  private queue: TaskQueue;
  private handler: TaskHandler;
  private workerConfig: WorkerConfig;
  private dlq?: DeadLetterQueue;
  private metrics?: MetricsCollector;
  private workers: Worker[] = [];
  private isStopped = false;
  private workerIdCounter = 0;
  private processedCount = 0;
  private failedCount = 0;

  constructor(
    queue: TaskQueue,
    handler: TaskHandler,
    workerConfig: WorkerConfig = {},
    dlq?: DeadLetterQueue
  ) {
    this.queue = queue;
    this.handler = handler;
    this.workerConfig = workerConfig;
    this.dlq = dlq;
  }

  public setDeadLetterQueue(dlq: DeadLetterQueue): void {
    this.dlq = dlq;
    for (const worker of this.workers) {
      worker.setDeadLetterQueue(dlq);
    }
  }

  public setHandler(handler: TaskHandler): void {
    this.handler = handler;
  }

  public setMetrics(metrics: MetricsCollector): void {
    this.metrics = metrics;
    for (const worker of this.workers) {
      worker.setMetrics(metrics);
    }
  }

  public getMetricsCollector(): MetricsCollector | undefined { return this.metrics; }
  public getDeadLetterQueue(): DeadLetterQueue | undefined { return this.dlq; }
  public getWorkers(): Worker[] { return [...this.workers]; }
  public getQueue(): TaskQueue { return this.queue; }
  public isPoolStopped(): boolean { return this.isStopped; }

  private wrappedHandler: TaskHandler = async (task: Task) => {
    try {
      const result = await this.handler(task);
      if (result.success) {
        this.processedCount++;
      } else {
        this.failedCount++;
      }
      return result;
    } catch (err) {
      this.failedCount++;
      throw err;
    }
  };

  private addWorker(): Worker {
    const workerId = `worker-${++this.workerIdCounter}`;
    const worker = new Worker(
      this.queue,
      this.wrappedHandler,
      { ...this.workerConfig, id: workerId },
      this.dlq
    );
    if (this.metrics) worker.setMetrics(this.metrics);
    this.workers.push(worker);
    if (!this.isStopped) worker.start();
    return worker;
  }

  public start(n: number): void {
    if (n < 0) throw new Error('Worker count must be non-negative');
    this.isStopped = false;
    if (this.workers.length > 0) {
      void this.scale(n);
      return;
    }
    for (let i = 0; i < n; i++) {
      this.addWorker();
    }
  }

  public async scale(n: number): Promise<void> {
    const target = Math.max(0, n);
    if (target > this.workers.length) {
      const toAdd = target - this.workers.length;
      for (let i = 0; i < toAdd; i++) {
        this.addWorker();
      }
    } else if (target < this.workers.length) {
      const toRemoveCount = this.workers.length - target;
      const workersToRemove = this.workers.splice(this.workers.length - toRemoveCount, toRemoveCount);
      await Promise.all(workersToRemove.map((w) => w.stop()));
    }
  }

  public async stop(timeoutMs = 30000): Promise<void> {
    this.isStopped = true;
    const stoppingWorkers = this.workers.splice(0, this.workers.length);
    const stopPromise = Promise.all(stoppingWorkers.map((w) => w.stop()));

    if (timeoutMs > 0) {
      let timer: NodeJS.Timeout | undefined;
      const timeoutPromise = new Promise<void>((_, reject) => {
        timer = setTimeout(() => {
          reject(new Error(`WorkerPool stop timed out after ${timeoutMs}ms`));
        }, timeoutMs);
        if (typeof timer.unref === 'function') timer.unref();
      });

      try {
        await Promise.race([stopPromise, timeoutPromise]);
      } catch {
        // Fallback gracefully on timeout
      } finally {
        if (timer) clearTimeout(timer);
      }
    } else {
      await stopPromise;
    }
  }

  public getStats(): WorkerPoolStats {
    const activeWorkers = this.workers.filter((w) => w.isBusy()).length;
    const idleWorkers = this.workers.filter((w) => !w.isBusy() && w.isRunning()).length;

    return {
      totalWorkers: this.workers.length,
      activeWorkers,
      idleWorkers,
      processedCount: this.processedCount,
      failedCount: this.failedCount,
    };
  }
}

import { Request, Response } from 'express';
import { randomUUID } from 'node:crypto';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';
import { Scheduler } from '../queue/scheduler.js';
import { MetricsCollector } from '../queue/metrics.js';

/**
 * Handles POST /api/v1/tasks — Enqueues a new task with optional priority, scheduling, and dependencies.
 */
export function createEnqueueHandler(queue: TaskQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const id = typeof body.id === 'string' && body.id.trim().length > 0 ? body.id : randomUUID();
      const priority = typeof body.priority === 'number' ? body.priority : 5;
      const maxAttempts = typeof body.maxAttempts === 'number' && body.maxAttempts > 0 ? body.maxAttempts : 3;
      const payload = body.payload !== undefined ? body.payload : body;

      let scheduledAt: Date | undefined;
      if (body.scheduledAt !== undefined && body.scheduledAt !== null) {
        scheduledAt = new Date(body.scheduledAt as string | number | Date);
        if (Number.isNaN(scheduledAt.getTime())) {
          res.status(400).json({ error: 'Invalid scheduledAt timestamp' });
          return;
        }
      }

      const isFuture = scheduledAt !== undefined && scheduledAt.getTime() > Date.now();
      const task: Task = {
        id,
        payload,
        priority,
        status: isFuture ? 'scheduled' : 'pending',
        createdAt: new Date(),
        attempts: 0,
        maxAttempts,
        ...(scheduledAt ? { scheduledAt } : {}),
        ...(Array.isArray(body.dependsOn) ? { dependsOn: body.dependsOn as string[] } : {}),
      };

      if (isFuture) {
        if (scheduler) {
          scheduler.schedule(task);
        } else {
          const delay = scheduledAt!.getTime() - Date.now();
          setTimeout(() => {
            task.status = 'pending';
            queue.enqueue(task);
          }, delay);
        }
      } else {
        queue.enqueue(task);
      }

      res.status(201).json(task);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };
}

/**
 * Handles GET /api/v1/metrics — Retrieves aggregated performance metrics.
 */
export function createMetricsHandler(metrics: MetricsCollector) {
  return (_req: Request, res: Response): void => {
    res.status(200).json(metrics.getMetrics());
  };
}

/**
 * Handles GET /api/v1/queue/stats — Retrieves real-time queue depth and worker telemetry.
 */
export function createQueueStatsHandler(queue: TaskQueue, pool?: WorkerPool, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (_req: Request, res: Response): void => {
    const poolStats = pool ? pool.getStats() : undefined;
    res.status(200).json({
      queueDepth: queue.size(),
      activeWorkers: poolStats?.activeWorkers ?? 0,
      totalWorkers: poolStats?.totalWorkers ?? 0,
      idleWorkers: poolStats?.idleWorkers ?? 0,
      processedCount: poolStats?.processedCount ?? 0,
      failedCount: poolStats?.failedCount ?? 0,
      dlqCount: dlq ? dlq.size() : 0,
      scheduledCount: scheduler ? scheduler.size() : 0,
    });
  };
}

/**
 * Handles POST /api/v1/workers/scale — Dynamically adjusts the number of workers in the pool.
 */
export function createScaleWorkersHandler(pool?: WorkerPool) {
  return async (req: Request, res: Response): Promise<void> => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const rawCount = body.count ?? body.workers ?? body.n ?? body.scale;
      const count = typeof rawCount === 'number' ? rawCount : typeof rawCount === 'string' ? parseInt(rawCount, 10) : undefined;

      if (count === undefined || Number.isNaN(count) || count < 0) {
        res.status(400).json({ error: 'Worker count must be a non-negative number' });
        return;
      }

      if (pool) {
        await pool.scale(count);
        res.status(200).json({
          message: `Scaled workers to ${count}`,
          count,
          totalWorkers: count,
          stats: pool.getStats(),
        });
        return;
      }

      res.status(200).json({ message: `Scaled workers to ${count}`, count, totalWorkers: count });
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };
}

/**
 * Handles GET /api/v1/dlq — Lists all dead-lettered task records.
 */
export function createListDlqHandler(dlq?: DeadLetterQueue) {
  return (_req: Request, res: Response): void => {
    res.status(200).json(dlq ? dlq.list() : []);
  };
}

/**
 * Handles POST /api/v1/dlq/:id/retry — Retries a task from the DLQ.
 */
export function createRetryDlqHandler(dlq?: DeadLetterQueue, queue?: TaskQueue) {
  return (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    if (!id) {
      res.status(400).json({ error: 'Task ID is required' });
      return;
    }
    const task = dlq && queue ? dlq.retry(id, queue) : null;
    if (!task) {
      res.status(404).json({ error: 'Task not found in dead-letter queue', id });
      return;
    }
    res.status(200).json({ message: `Task ${id} retried successfully`, task, ...task });
  };
}

/**
 * Handles GET /api/v1/tasks/:id — Retrieves single task status.
 */
export function createGetTaskByIdHandler(queue: TaskQueue, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const task = queue.getTask(id) ?? dlq?.get(id)?.task ?? scheduler?.getTask(id);
    if (!task) {
      res.status(404).json({ error: 'Task not found', id });
      return;
    }
    res.status(200).json(task);
  };
}

/**
 * Handles GET /api/v1/tasks — Lists tasks with status filter.
 */
export function createListTasksHandler(queue: TaskQueue, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    const { status } = req.query;
    let tasks = queue.getAllTasks();
    const existingIds = new Set(tasks.map((t) => t.id));

    if (dlq) {
      for (const dt of dlq.list().map((e) => e.task)) {
        if (!existingIds.has(dt.id)) {
          tasks.push(dt);
          existingIds.add(dt.id);
        }
      }
    }
    if (scheduler) {
      for (const st of scheduler.getScheduledTasks()) {
        if (!existingIds.has(st.id)) {
          tasks.push(st);
          existingIds.add(st.id);
        }
      }
    }

    if (typeof status === 'string' && status.trim().length > 0) {
      tasks = tasks.filter((t) => t.status === status);
    }
    res.status(200).json(tasks);
  };
}

import { Router } from 'express';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';
import { Scheduler } from '../queue/scheduler.js';
import { MetricsCollector } from '../queue/metrics.js';
import {
  createEnqueueHandler,
  createMetricsHandler,
  createQueueStatsHandler,
  createScaleWorkersHandler,
  createListDlqHandler,
  createRetryDlqHandler,
  createGetTaskByIdHandler,
  createListTasksHandler,
} from './queue-handlers.js';

export const defaultQueue = new TaskQueue();
export const defaultDlq = new DeadLetterQueue(defaultQueue);
export const defaultPool = new WorkerPool(
  defaultQueue,
  async (task: Task) => ({ success: true, data: task.payload }),
  { pollIntervalMs: 20 },
  defaultDlq
);
export const defaultScheduler = new Scheduler(defaultQueue, { checkIntervalMs: 1000 });
export const defaultMetrics = new MetricsCollector(defaultQueue);
defaultPool.setMetrics(defaultMetrics);
defaultMetrics.start(1000);

export interface QueueRouterOptions {
  queue?: TaskQueue;
  dlq?: DeadLetterQueue;
  pool?: WorkerPool;
  scheduler?: Scheduler;
  metrics?: MetricsCollector;
}

/**
 * Creates and configures an Express router for queue REST API operations.
 *
 * @param options - Configuration options and dependency overrides.
 * @returns Configured Express Router.
 */
export function createQueueRouter(options: QueueRouterOptions = {}): Router {
  const router = Router();
  const queue = options.queue ?? defaultQueue;
  const dlq = options.dlq ?? defaultDlq;
  const pool = options.pool ?? defaultPool;
  const scheduler = options.scheduler ?? defaultScheduler;
  const metrics = options.metrics ?? defaultMetrics;

  router.post(['/tasks', '/api/v1/tasks'], createEnqueueHandler(queue, scheduler));
  router.get(['/metrics', '/api/v1/metrics'], createMetricsHandler(metrics));
  router.get(['/queue/stats', '/api/v1/queue/stats'], createQueueStatsHandler(queue, pool, dlq, scheduler));
  router.post(['/workers/scale', '/api/v1/workers/scale'], createScaleWorkersHandler(pool));
  router.get(['/dlq', '/api/v1/dlq'], createListDlqHandler(dlq));
  router.post(['/dlq/:id/retry', '/api/v1/dlq/:id/retry'], createRetryDlqHandler(dlq, queue));
  router.get(['/tasks/:id', '/api/v1/tasks/:id'], createGetTaskByIdHandler(queue, dlq, scheduler));
  router.get(['/tasks', '/api/v1/tasks'], createListTasksHandler(queue, dlq, scheduler));

  return router;
}

export const queueRouter = createQueueRouter();
export default queueRouter;

import { Request, Response } from 'express';
import { randomUUID } from 'node:crypto';
import { Task } from '../queue/types.js';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { Scheduler } from '../queue/scheduler.js';

/**
 * Handles POST /api/v1/tasks — Enqueues a new task with optional priority, scheduling, and dependencies.
 */
export function createEnqueueHandler(queue: TaskQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const id = typeof body.id === 'string' && body.id.trim().length > 0 ? body.id : randomUUID();
      const priority = typeof body.priority === 'number' ? body.priority : 5;
      const maxAttempts = typeof body.maxAttempts === 'number' && body.maxAttempts > 0 ? body.maxAttempts : 3;
      const payload = body.payload !== undefined ? body.payload : body;

      let scheduledAt: Date | undefined;
      if (body.scheduledAt !== undefined && body.scheduledAt !== null) {
        scheduledAt = new Date(body.scheduledAt as string | number | Date);
        if (Number.isNaN(scheduledAt.getTime())) {
          res.status(400).json({ error: 'Invalid scheduledAt timestamp' });
          return;
        }
      }

      const isFuture = scheduledAt !== undefined && scheduledAt.getTime() > Date.now();
      const task: Task = {
        id,
        payload,
        priority,
        status: isFuture ? 'scheduled' : 'pending',
        createdAt: new Date(),
        attempts: 0,
        maxAttempts,
        ...(scheduledAt ? { scheduledAt } : {}),
        ...(Array.isArray(body.dependsOn) ? { dependsOn: body.dependsOn as string[] } : {}),
      };

      if (isFuture) {
        if (scheduler) {
          scheduler.schedule(task);
        } else {
          const delay = scheduledAt!.getTime() - Date.now();
          setTimeout(() => {
            task.status = 'pending';
            queue.enqueue(task);
          }, delay);
        }
      } else {
        queue.enqueue(task);
      }

      res.status(201).json(task);
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };
}

/**
 * Handles GET /api/v1/tasks/:id — Retrieves single task status.
 */
export function createGetTaskByIdHandler(queue: TaskQueue, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    const task = queue.getTask(id) ?? dlq?.get(id)?.task ?? scheduler?.getTask(id);
    if (!task) {
      res.status(404).json({ error: 'Task not found', id });
      return;
    }
    res.status(200).json(task);
  };
}

/**
 * Handles GET /api/v1/tasks — Lists tasks with status filter.
 */
export function createListTasksHandler(queue: TaskQueue, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (req: Request, res: Response): void => {
    const { status } = req.query;
    let tasks = queue.getAllTasks();
    const existingIds = new Set(tasks.map((t) => t.id));

    if (dlq) {
      for (const dt of dlq.list().map((e) => e.task)) {
        if (!existingIds.has(dt.id)) {
          tasks.push(dt);
          existingIds.add(dt.id);
        }
      }
    }
    if (scheduler) {
      for (const st of scheduler.getScheduledTasks()) {
        if (!existingIds.has(st.id)) {
          tasks.push(st);
          existingIds.add(st.id);
        }
      }
    }

    if (typeof status === 'string' && status.trim().length > 0) {
      tasks = tasks.filter((t) => t.status === status);
    }
    res.status(200).json(tasks);
  };
}

import { Request, Response } from 'express';
import { TaskQueue } from '../queue/task-queue.js';
import { DeadLetterQueue } from '../queue/dead-letter-queue.js';
import { WorkerPool } from '../queue/worker-pool.js';
import { Scheduler } from '../queue/scheduler.js';
import { MetricsCollector } from '../queue/metrics.js';

/**
 * Handles GET /api/v1/metrics — Retrieves aggregated performance metrics.
 */
export function createMetricsHandler(metrics: MetricsCollector) {
  return (_req: Request, res: Response): void => {
    res.status(200).json(metrics.getMetrics());
  };
}

/**
 * Handles GET /api/v1/queue/stats — Retrieves real-time queue depth and worker telemetry.
 */
export function createQueueStatsHandler(queue: TaskQueue, pool?: WorkerPool, dlq?: DeadLetterQueue, scheduler?: Scheduler) {
  return (_req: Request, res: Response): void => {
    const poolStats = pool ? pool.getStats() : undefined;
    res.status(200).json({
      queueDepth: queue.size(),
      activeWorkers: poolStats?.activeWorkers ?? 0,
      totalWorkers: poolStats?.totalWorkers ?? 0,
      idleWorkers: poolStats?.idleWorkers ?? 0,
      processedCount: poolStats?.processedCount ?? 0,
      failedCount: poolStats?.failedCount ?? 0,
      dlqCount: dlq ? dlq.size() : 0,
      scheduledCount: scheduler ? scheduler.size() : 0,
    });
  };
}

/**
 * Handles POST /api/v1/workers/scale — Dynamically adjusts the number of workers in the pool.
 */
export function createScaleWorkersHandler(pool?: WorkerPool) {
  return async (req: Request, res: Response): Promise<void> => {
    try {
      const body = (typeof req.body === 'object' && req.body !== null ? req.body : {}) as Record<string, unknown>;
      const rawCount = body.count ?? body.workers ?? body.n ?? body.scale;
      const count = typeof rawCount === 'number' ? rawCount : typeof rawCount === 'string' ? parseInt(rawCount, 10) : undefined;

      if (count === undefined || Number.isNaN(count) || count < 0) {
        res.status(400).json({ error: 'Worker count must be a non-negative number' });
        return;
      }

      if (pool) {
        await pool.scale(count);
        res.status(200).json({
          message: `Scaled workers to ${count}`,
          count,
          totalWorkers: count,
          stats: pool.getStats(),
        });
        return;
      }

      res.status(200).json({ message: `Scaled workers to ${count}`, count, totalWorkers: count });
    } catch (err) {
      const error = err instanceof Error ? err.message : String(err);
      res.status(500).json({ error });
    }
  };
}

/**
 * Handles GET /api/v1/dlq — Lists all dead-lettered task records.
 */
export function createListDlqHandler(dlq?: DeadLetterQueue) {
  return (_req: Request, res: Response): void => {
    res.status(200).json(dlq ? dlq.list() : []);
  };
}

/**
 * Handles POST /api/v1/dlq/:id/retry — Retries a task from the DLQ.
 */
export function createRetryDlqHandler(dlq?: DeadLetterQueue, queue?: TaskQueue) {
  return (req: Request, res: Response): void => {
    const rawId = req.params.id;
    const id = typeof rawId === 'string' ? rawId : Array.isArray(rawId) ? rawId[0] : '';
    if (!id) {
      res.status(400).json({ error: 'Task ID is required' });
      return;
    }
    const task = dlq && queue ? dlq.retry(id, queue) : null;
    if (!task) {
      res.status(404).json({ error: 'Task not found in dead-letter queue', id });
      return;
    }
    res.status(200).json({ message: `Task ${id} retried successfully`, task, ...task });
  };
}

