import { WorkerConfig, Task } from './types.js';
import { TaskQueue } from './task-queue.js';

/**
 * Calculates exponential backoff delay based on attempts count.
 *
 * @param attempts - Number of attempts made.
 * @param config - WorkerConfig containing backoff settings.
 * @returns Delay in milliseconds.
 */
export function calculateBackoff(attempts: number, config: WorkerConfig): number {
  const initial = config.initialBackoffMs ?? 100;
  const multiplier = config.backoffMultiplier ?? 2;
  const max = config.maxBackoffMs ?? 10000;
  const delay = initial * Math.pow(multiplier, Math.max(0, attempts - 1));
  return Math.min(delay, max);
}

/**
 * Schedules a failed task for re-enqueueing after an exponential backoff delay.
 *
 * @param task - The task to retry.
 * @param queue - The destination TaskQueue.
 * @param config - Worker configuration containing backoff settings.
 * @param onScheduled - Callback receiving the active timer when scheduled.
 * @param onFired - Optional callback receiving the timer when expired.
 * @returns The calculated delay in milliseconds.
 */
export function scheduleTaskRetry(
  task: Task,
  queue: TaskQueue,
  config: WorkerConfig,
  onScheduled: (timer: NodeJS.Timeout) => void,
  onFired?: (timer: NodeJS.Timeout) => void
): number {
  const delay = calculateBackoff(task.attempts, config);
  const timer = setTimeout(() => {
    onFired?.(timer);
    task.status = 'pending';
    queue.enqueue(task);
  }, delay);
  onScheduled(timer);
  return delay;
}

